insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-sancocho-ligero-de-pollo','Sancocho ligero de pollo','lunch','pollo','sopa',50,567.1,44.7,84.1,5.6,8.5,'[{"food":"pechuga","g":130,"role":"protein","label":"en presa"},{"food":"yuca","g":90,"role":"carb"},{"food":"name","g":70,"role":"carb"},{"food":"platano_verde","g":40,"role":"carb"},{"food":"ahuyama","g":100,"role":"veg"},{"food":"zanahoria","g":40,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"especias","g":5,"role":"fixed","label":"cilantro"}]'::jsonb,'["Pon a hervir 1 litro de agua con cebolla, ajo y sal. Añade la pechuga y cocina 15 minutos.","Agrega yuca, ñame, plátano verde y zanahoria en trozos; cocina 20 minutos.","Suma la ahuyama y cocina 10 minutos más hasta que todo esté tierno y el pollo bien cocido.","Termina con cilantro picado. Sirve en plato hondo, retirando el exceso de grasa del caldo."]'::jsonb,array['almuerzo','pollo','plato de la casa','sopa','caribeña']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-lentejas-con-pollo-desmechado-y-arroz','Lentejas con pollo desmechado y arroz','lunch','legumbre','legumbre',45,541.8,48.6,64,9.6,14.8,'[{"food":"lentejas","g":160,"role":"fixed"},{"food":"pechuga","g":100,"role":"protein","label":"desmechada"},{"food":"arroz","g":90,"role":"carb"},{"food":"zanahoria","g":40,"role":"veg"},{"food":"cebolla","g":40,"role":"veg"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Remoja las lentejas 30 minutos si tienes tiempo y cuécelas con zanahoria picada, cebolla, ajo y sal 25 minutos.","Cuece la pechuga 15 minutos y desmécha.","Mezcla el pollo con las lentejas y cocina 5 minutos.","Sirve con el arroz blanco cocido aparte."]'::jsonb,array['almuerzo','legumbre','plato de la casa','legumbres','hierro']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-frijoles-con-carne-magra-y-arroz','Frijoles con carne magra y arroz','lunch','res','legumbre',55,596,47.3,68.3,15.4,13.2,'[{"food":"frijoles","g":150,"role":"fixed"},{"food":"res","g":105,"role":"protein","label":"en cubos"},{"food":"arroz","g":100,"role":"carb"},{"food":"aguacate","g":40,"role":"fat"},{"food":"cebolla","g":30,"role":"veg"}]'::jsonb,'["Cuece los frijoles (previamente remojados) con cebolla y ajo hasta que estén blandos, unos 40 minutos.","Cocina la res magra en cubos con sal y comino 20 minutos hasta que esté tierna y sin rosado.","Mezcla la carne con los frijoles. Sirve con arroz y aguacate en láminas."]'::jsonb,array['almuerzo','res','plato de la casa','legumbres','hierro']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
