insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-mojarra-al-horno-con-patacon-de-platano-verde','Mojarra al horno con patacón de plátano verde','lunch','mojarra','pescado',45,440,46.5,41.7,10.6,4.3,'[{"food":"mojarra","g":170,"role":"protein","label":"entera o filete"},{"food":"platano_verde","g":100,"role":"carb"},{"food":"lechuga","g":50,"role":"veg"},{"food":"zanahoria","g":40,"role":"veg"},{"food":"limon","g":15,"role":"fixed"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Haz cortes superficiales a la mojarra, sazónala con sal, ajo y limón y hornéala a 200 °C por 25 minutos.","Corta el plátano verde en rodajas gruesas, hornea 10 minutos, aplástalas y hornea 8 minutos más hasta que estén doradas.","Sirve con ensalada de lechuga y zanahoria rallada."]'::jsonb,array['almuerzo','mojarra','plato de la casa','caribeña','omega 3']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
