insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-carne-desmechada-con-arroz-y-platano-maduro','Carne desmechada con arroz y plátano maduro','lunch','res','res',60,586.7,44.1,66.1,16.7,4,'[{"food":"res","g":135,"role":"protein","label":"desmechada"},{"food":"cebolla","g":50,"role":"veg"},{"food":"pimenton","g":40,"role":"veg"},{"food":"arroz","g":120,"role":"carb"},{"food":"platano_maduro","g":80,"role":"carb"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Hierve la res magra en agua con cebolla y ajo 40 minutos hasta que esté muy blanda; desmecha.","Sofríe cebolla y pimentón en tiras, agrega la carne, comino, sal y un chorrito del caldo; cocina 8 minutos.","Hornea el plátano maduro en tajadas 15 minutos. Sirve con el arroz."]'::jsonb,array['almuerzo','res','plato de la casa','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
