insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-cerdo-a-la-plancha-con-pure-de-ahuyama-y-habichuela','Cerdo a la plancha con puré de ahuyama y habichuela','lunch','cerdo','cerdo',30,431,43.6,33.9,14.2,6.2,'[{"food":"cerdo","g":145,"role":"protein","label":"a la plancha"},{"food":"ahuyama","g":150,"role":"veg"},{"food":"habichuela","g":80,"role":"veg"},{"food":"papa_criolla","g":70,"role":"carb"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Sazona el lomo con sal, ajo y orégano y cocínalo a la plancha 6 minutos por lado hasta que esté bien cocido.","Haz el puré con ahuyama cocida y papa criolla. Saltea la habichuela 5 minutos y sirve."]'::jsonb,array['almuerzo','cerdo','plato de la casa','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-albondigas-de-res-magra-con-arroz-integral-y-ensalada','Albóndigas de res magra con arroz integral y ensalada','lunch','res','res',40,480.6,47.5,40.9,13.6,4.6,'[{"food":"molida","g":150,"role":"protein","label":"en albóndigas"},{"food":"clara","g":33,"role":"protein"},{"food":"arroz_int","g":130,"role":"carb"},{"food":"lechuga","g":50,"role":"veg"},{"food":"zanahoria","g":40,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"}]'::jsonb,'["Mezcla la carne con cebolla rallada, clara, sal y comino; forma albóndigas.","Hornea 20 minutos a 200 °C, hasta que no queden rosadas por dentro.","Sirve con arroz integral y ensalada de lechuga con zanahoria."]'::jsonb,array['almuerzo','res','plato de la casa','meal prep']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-garbanzos-guisados-con-pollo-y-espinaca','Garbanzos guisados con pollo y espinaca','lunch','legumbre','legumbre',35,577.2,48.5,66.8,12.8,13.6,'[{"food":"garbanzo","g":140,"role":"fixed"},{"food":"pechuga","g":100,"role":"protein"},{"food":"espinaca","g":80,"role":"veg"},{"food":"cebolla","g":40,"role":"veg"},{"food":"arroz","g":80,"role":"carb"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Sofríe cebolla y ajo; agrega el pollo en cubos y sella 4 minutos.","Suma garbanzos cocidos, comino, sal y medio vaso de agua; cocina 10 minutos.","Incorpora la espinaca 2 minutos antes de apagar. Sirve con el arroz."]'::jsonb,array['almuerzo','legumbre','plato de la casa','hierro','folato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-salmon-al-horno-con-quinua-y-habichuelas','Salmón al horno con quinua y habichuelas','lunch','salmon','pescado',30,571,45.1,36.3,26.2,6.8,'[{"food":"salmon","g":170,"role":"protein","label":"bien cocido"},{"food":"quinua","g":130,"role":"carb"},{"food":"habichuela","g":100,"role":"veg"},{"food":"limon","g":15,"role":"fixed"},{"food":"aceite","g":3,"role":"fat"}]'::jsonb,'["Sazona el salmón con sal, ajo y limón y hornéalo a 200 °C por 15–18 minutos, hasta que esté bien cocido por dentro.","Cuece la quinua 15 minutos y saltea las habichuelas 5 minutos. Sirve."]'::jsonb,array['almuerzo','salmon','plato de la casa','omega 3']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-pavo-salteado-con-quinua-y-verduras','Pavo salteado con quinua y verduras','lunch','pavo','pollo',30,422.2,46.7,36.6,9.3,6.8,'[{"food":"pavo","g":130,"role":"protein","label":"en tiras"},{"food":"quinua","g":130,"role":"carb"},{"food":"calabacin","g":100,"role":"veg"},{"food":"pimenton","g":50,"role":"veg"},{"food":"zanahoria","g":40,"role":"veg"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Saltea el pavo en tiras con sal y comino 6 minutos hasta que esté bien cocido.","Agrega calabacín, pimentón y zanahoria y cocina 5 minutos. Mezcla con la quinua cocida."]'::jsonb,array['almuerzo','pavo','plato de la casa','rápido']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-tortitas-de-pollo-y-ahuyama-con-ensalada-de-repollo','Tortitas de pollo y ahuyama con ensalada de repollo','lunch','pollo','pollo',35,422.4,50.9,30.9,10.3,6.3,'[{"food":"pechuga","g":125,"role":"protein","label":"molida cocida"},{"food":"clara","g":66,"role":"protein"},{"food":"ahuyama","g":100,"role":"carb"},{"food":"avena","g":20,"role":"carb"},{"food":"repollo","g":80,"role":"veg"},{"food":"zanahoria","g":30,"role":"veg"},{"food":"aceite","g":4,"role":"fat"}]'::jsonb,'["Procesa la pechuga cocida con la ahuyama cocida, las claras, la avena, sal y comino.","Forma tortitas y dóralas en sartén antiadherente 4 minutos por lado.","Acompaña con ensalada de repollo y zanahoria con limón."]'::jsonb,array['almuerzo','pollo','plato de la casa','meal prep']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-pechuga-de-pollo-a-la-plancha-con-ajo-y-limon-con-arroz-integral-y-espinacas-con-champinones','Pechuga de pollo a la plancha con ajo y limón con arroz integral y espinacas con champiñones','lunch','pollo','pollo',50,480.6,48.6,44.5,11.7,5.2,'[{"food":"pechuga","g":130,"role":"protein","label":"cocida"},{"food":"aceite","g":5,"role":"fat"},{"food":"limon","g":10,"role":"fixed"},{"food":"arroz_int","g":150,"role":"carb"},{"food":"espinaca","g":80,"role":"veg"},{"food":"champi","g":60,"role":"veg"}]'::jsonb,'["Sazona pechuga de pollo con ajo, comino, sal y jugo de limón; déjala reposar 15 minutos.","Sella en una sartén antiadherente con 1 cucharadita de aceite, 5–6 minutos por lado hasta que esté completamente cocida (temperatura interna de 74 °C si usas termómetro); sin partes rosadas por dentro.","Deja reposar 3 minutos antes de cortar en tiras.","Cocina el arroz integral con 2,5 partes de agua a fuego bajo y tapado por 35 minutos; deja reposar 5.","Saltea los champiñones laminados con ajo 4 minutos, añade la espinaca y cocina 2 minutos hasta que se marchite.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','pollo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-pechuga-de-pollo-desmechada-con-cebolla-y-pimenton-con-platano-maduro-al-horno-y-pimenton-y-cebolla-salteados','Pechuga de pollo desmechada con cebolla y pimentón con plátano maduro al horno y pimentón y cebolla salteados','lunch','pollo','pollo',55,453.9,43.5,47.3,10.5,6.4,'[{"food":"pechuga","g":130,"role":"protein","label":"cocida"},{"food":"cebolla","g":90,"role":"veg"},{"food":"pimenton","g":120,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"platano_maduro","g":100,"role":"carb"}]'::jsonb,'["Hierve pechuga de pollo en agua con cebolla, ajo y sal 25 minutos hasta que esté muy tierna.","Desmecha con dos tenedores.","Sofríe cebolla y pimentón en tiras con 1 cucharadita de aceite 5 minutos, agrega la carne desmechada y cocina 5 minutos más.","Corta el plátano maduro en tajadas, rocíalas con apenas una gota de aceite y hornéalas a 200 °C por 15 minutos, volteando a la mitad.","Corta el pimentón y la cebolla en tiras y saltéalos 6 minutos con una cucharadita de aceite hasta que estén dorados.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','pollo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-pechuga-de-pollo-al-horno-con-hierbas-con-arroz-blanco-y-ensalada-de-repollo-y-zanahoria','Pechuga de pollo al horno con hierbas con arroz blanco y ensalada de repollo y zanahoria','lunch','pollo','pollo',50,500.6,46.1,53.2,10.4,4.5,'[{"food":"pechuga","g":130,"role":"protein","label":"cocida"},{"food":"aceite","g":5,"role":"fat"},{"food":"limon","g":20,"role":"fixed"},{"food":"arroz","g":150,"role":"carb"},{"food":"repollo","g":100,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"}]'::jsonb,'["Calienta el horno a 200 °C. Sazona pechuga de pollo con ajo, tomillo, orégano, sal y limón.","Hornea 20–25 minutos hasta que esté bien cocida y jugosa; voltea a la mitad.","Reposa 5 minutos antes de servir.","Cocina el arroz con el doble de agua, una pizca de sal y tapa a fuego bajo 18 minutos; suelta con un tenedor.","Ralla el repollo y la zanahoria, aliña con jugo de limón, sal y una cucharadita de aceite de oliva.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','pollo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-pechuga-de-pollo-guisada-con-champinones-y-cebolla-larga-con-name-cocido-y-pure-de-ahuyama','Pechuga de pollo guisada con champiñones y cebolla larga con ñame cocido y puré de ahuyama','lunch','pollo','pollo',45,489.1,45.7,53.7,10.3,8.2,'[{"food":"pechuga","g":130,"role":"protein","label":"cocida"},{"food":"champi","g":60,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"name","g":120,"role":"carb"},{"food":"ahuyama","g":150,"role":"veg"}]'::jsonb,'["Sofríe cebolla larga picada y ajo con 1 cucharadita de aceite 3 minutos.","Agrega pechuga de pollo en cubos y sella 4 minutos; suma los champiñones laminados y medio vaso de agua.","Tapa y cocina a fuego bajo 15 minutos hasta que espese y la carne esté totalmente cocida.","Pela el ñame, córtalo en trozos y hiérvelo 20 minutos con una pizca de sal hasta que un tenedor lo atraviese sin resistencia.","Cocina la ahuyama en trozos 15 minutos, escúrrela y aplástala con sal y una pizca de comino.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','pollo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-pechuga-de-pollo-en-brocheta-con-pimenton-y-cebolla-con-quinua-y-ensalada-de-lechuga-y-aguacate','Pechuga de pollo en brocheta con pimentón y cebolla con quinua y ensalada de lechuga y aguacate','lunch','pollo','pollo',45,544.4,49.7,43.6,18.8,9.5,'[{"food":"pechuga","g":130,"role":"protein","label":"cocida"},{"food":"pimenton","g":50,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"quinua","g":150,"role":"carb"},{"food":"lechuga","g":80,"role":"veg"},{"food":"aguacate","g":40,"role":"fat"},{"food":"limon","g":10,"role":"fixed"}]'::jsonb,'["Corta pechuga de pollo en cubos de 3 cm y alterna en palitos con tiras de pimentón y cebolla.","Sazona con sal, ajo, comino y limón.","Asa en sartén o parrilla 12–15 minutos girando para que se cocine por todos los lados.","Enjuaga la quinua, cuécela con el doble de agua 15 minutos y deja reposar tapada 5 minutos.","Lava bien la lechuga, trocéala y mezcla con el aguacate en cubos, limón y sal.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','pollo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-muslo-de-pollo-sin-piel-a-la-plancha-con-ajo-y-limon-con-yuca-cocida-y-berenjena-al-horno','Muslo de pollo sin piel a la plancha con ajo y limón con yuca cocida y berenjena al horno','lunch','pollo','pollo',40,562.2,43.2,59.4,18.1,5.9,'[{"food":"muslo","g":155,"role":"protein","label":"cocida"},{"food":"aceite","g":5,"role":"fat"},{"food":"limon","g":10,"role":"fixed"},{"food":"yuca","g":120,"role":"carb"},{"food":"berenjena","g":150,"role":"veg"}]'::jsonb,'["Sazona muslo de pollo sin piel con ajo, comino, sal y jugo de limón; déjala reposar 15 minutos.","Sella en una sartén antiadherente con 1 cucharadita de aceite, 5–6 minutos por lado hasta que esté completamente cocida (temperatura interna de 74 °C si usas termómetro); sin partes rosadas por dentro.","Deja reposar 3 minutos antes de cortar en tiras.","Pela la yuca, pártela en trozos y hiérvela con sal 20–25 minutos hasta que esté blanda; retira el hilo central.","Corta la berenjena en rodajas, sazona con sal, ajo y comino y hornea a 200 °C por 20 minutos.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','pollo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-muslo-de-pollo-sin-piel-desmechada-con-cebolla-y-pimenton-con-papa-criolla-y-habichuela-y-zanahoria-salteadas','Muslo de pollo sin piel desmechada con cebolla y pimentón con papa criolla y habichuela y zanahoria salteadas','lunch','pollo','pollo',50,494.9,45.7,38.7,18.1,8.2,'[{"food":"muslo","g":155,"role":"protein","label":"cocida"},{"food":"cebolla","g":40,"role":"veg"},{"food":"pimenton","g":40,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"papa_criolla","g":120,"role":"carb"},{"food":"habichuela","g":90,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"}]'::jsonb,'["Hierve muslo de pollo sin piel en agua con cebolla, ajo y sal 25 minutos hasta que esté muy tierna.","Desmecha con dos tenedores.","Sofríe cebolla y pimentón en tiras con 1 cucharadita de aceite 5 minutos, agrega la carne desmechada y cocina 5 minutos más.","Hierve las papas criollas con cáscara y sal 15 minutos; escurre y sirve.","Saltea la habichuela y la zanahoria en juliana con cebolla larga y 1 cucharadita de aceite 6 minutos; deben quedar tiernas pero crujientes.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','pollo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-muslo-de-pollo-sin-piel-al-horno-con-hierbas-con-arroz-integral-y-calabacin-salteado','Muslo de pollo sin piel al horno con hierbas con arroz integral y calabacín salteado','lunch','pollo','pollo',65,541.4,46.6,46.8,19.4,4.8,'[{"food":"muslo","g":155,"role":"protein","label":"cocida"},{"food":"aceite","g":5,"role":"fat"},{"food":"limon","g":10,"role":"fixed"},{"food":"arroz_int","g":150,"role":"carb"},{"food":"calabacin","g":160,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"}]'::jsonb,'["Calienta el horno a 200 °C. Sazona muslo de pollo sin piel con ajo, tomillo, orégano, sal y limón.","Hornea 20–25 minutos hasta que esté bien cocida y jugosa; voltea a la mitad.","Reposa 5 minutos antes de servir.","Cocina el arroz integral con 2,5 partes de agua a fuego bajo y tapado por 35 minutos; deja reposar 5.","Corta el calabacín en medias lunas y saltéalo con cebolla 5 minutos a fuego alto para que no suelte agua.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','pollo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-muslo-de-pollo-sin-piel-guisada-con-champinones-y-cebolla-larga-con-platano-maduro-al-horno-y-espinacas-con-champinones','Muslo de pollo sin piel guisada con champiñones y cebolla larga con plátano maduro al horno y espinacas con champiñones','lunch','pollo','pollo',45,501.5,47.6,42.5,18.5,5.9,'[{"food":"muslo","g":155,"role":"protein","label":"cocida"},{"food":"champi","g":120,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"platano_maduro","g":100,"role":"carb"},{"food":"espinaca","g":80,"role":"veg"}]'::jsonb,'["Sofríe cebolla larga picada y ajo con 1 cucharadita de aceite 3 minutos.","Agrega muslo de pollo sin piel en cubos y sella 4 minutos; suma los champiñones laminados y medio vaso de agua.","Tapa y cocina a fuego bajo 15 minutos hasta que espese y la carne esté totalmente cocida.","Corta el plátano maduro en tajadas, rocíalas con apenas una gota de aceite y hornéalas a 200 °C por 15 minutos, volteando a la mitad.","Saltea los champiñones laminados con ajo 4 minutos, añade la espinaca y cocina 2 minutos hasta que se marchite.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','pollo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-muslo-de-pollo-sin-piel-en-brocheta-con-pimenton-y-cebolla-con-arroz-blanco-y-pimenton-y-cebolla-salteados','Muslo de pollo sin piel en brocheta con pimentón y cebolla con arroz blanco y pimentón y cebolla salteados','lunch','pollo','pollo',45,582.8,46.5,57,18.3,4.7,'[{"food":"muslo","g":155,"role":"protein","label":"cocida"},{"food":"pimenton","g":130,"role":"veg"},{"food":"cebolla","g":80,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"arroz","g":150,"role":"carb"}]'::jsonb,'["Corta muslo de pollo sin piel en cubos de 3 cm y alterna en palitos con tiras de pimentón y cebolla.","Sazona con sal, ajo, comino y limón.","Asa en sartén o parrilla 12–15 minutos girando para que se cocine por todos los lados.","Cocina el arroz con el doble de agua, una pizca de sal y tapa a fuego bajo 18 minutos; suelta con un tenedor.","Corta el pimentón y la cebolla en tiras y saltéalos 6 minutos con una cucharadita de aceite hasta que estén dorados.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','pollo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
