insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-res-magra-en-brocheta-con-pimenton-y-cebolla-con-arroz-integral-y-habichuela-y-zanahoria-salteadas','Res magra en brocheta con pimentón y cebolla con arroz integral y habichuela y zanahoria salteadas','lunch','res','res',60,571.2,47.6,55.2,18.3,8.5,'[{"food":"res","g":140,"role":"protein","label":"cocida"},{"food":"pimenton","g":50,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"arroz_int","g":150,"role":"carb"},{"food":"habichuela","g":90,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"}]'::jsonb,'["Corta res magra en cubos de 3 cm y alterna en palitos con tiras de pimentón y cebolla.","Sazona con sal, ajo, comino y limón.","Asa en sartén o parrilla 12–15 minutos girando para que se cocine por todos los lados.","Cocina el arroz integral con 2,5 partes de agua a fuego bajo y tapado por 35 minutos; deja reposar 5.","Saltea la habichuela y la zanahoria en juliana con cebolla larga y 1 cucharadita de aceite 6 minutos; deben quedar tiernas pero crujientes.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','res','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-lomo-de-cerdo-magro-a-la-plancha-con-ajo-y-limon-con-platano-maduro-al-horno-y-calabacin-salteado','Lomo de cerdo magro a la plancha con ajo y limón con plátano maduro al horno y calabacín salteado','lunch','cerdo','cerdo',35,446.9,42.4,40.4,14.6,4.4,'[{"food":"cerdo","g":145,"role":"protein","label":"cocida"},{"food":"aceite","g":5,"role":"fat"},{"food":"limon","g":10,"role":"fixed"},{"food":"platano_maduro","g":100,"role":"carb"},{"food":"calabacin","g":160,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"}]'::jsonb,'["Sazona lomo de cerdo magro con ajo, comino, sal y jugo de limón; déjala reposar 15 minutos.","Sella en una sartén antiadherente con 1 cucharadita de aceite, 5–6 minutos por lado hasta que esté completamente cocida (temperatura interna de 74 °C si usas termómetro); sin partes rosadas por dentro.","Deja reposar 3 minutos antes de cortar en tiras.","Corta el plátano maduro en tajadas, rocíalas con apenas una gota de aceite y hornéalas a 200 °C por 15 minutos, volteando a la mitad.","Corta el calabacín en medias lunas y saltéalo con cebolla 5 minutos a fuego alto para que no suelte agua.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','cerdo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-lomo-de-cerdo-magro-desmechada-con-cebolla-y-pimenton-con-arroz-blanco-y-espinacas-con-champinones','Lomo de cerdo magro desmechada con cebolla y pimentón con arroz blanco y espinacas con champiñones','lunch','cerdo','cerdo',55,542.1,48.2,53.4,14.8,4.6,'[{"food":"cerdo","g":145,"role":"protein","label":"cocida"},{"food":"cebolla","g":40,"role":"veg"},{"food":"pimenton","g":40,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"arroz","g":150,"role":"carb"},{"food":"espinaca","g":80,"role":"veg"},{"food":"champi","g":60,"role":"veg"}]'::jsonb,'["Hierve lomo de cerdo magro en agua con cebolla, ajo y sal 25 minutos hasta que esté muy tierna.","Desmecha con dos tenedores.","Sofríe cebolla y pimentón en tiras con 1 cucharadita de aceite 5 minutos, agrega la carne desmechada y cocina 5 minutos más.","Cocina el arroz con el doble de agua, una pizca de sal y tapa a fuego bajo 18 minutos; suelta con un tenedor.","Saltea los champiñones laminados con ajo 4 minutos, añade la espinaca y cocina 2 minutos hasta que se marchite.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','cerdo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-lomo-de-cerdo-magro-al-horno-con-hierbas-con-name-cocido-y-pimenton-y-cebolla-salteados','Lomo de cerdo magro al horno con hierbas con ñame cocido y pimentón y cebolla salteados','lunch','cerdo','cerdo',50,472.1,42.3,43.6,14.3,7.3,'[{"food":"cerdo","g":145,"role":"protein","label":"cocida"},{"food":"aceite","g":5,"role":"fat"},{"food":"limon","g":10,"role":"fixed"},{"food":"name","g":120,"role":"carb"},{"food":"pimenton","g":80,"role":"veg"},{"food":"cebolla","g":50,"role":"veg"}]'::jsonb,'["Calienta el horno a 200 °C. Sazona lomo de cerdo magro con ajo, tomillo, orégano, sal y limón.","Hornea 20–25 minutos hasta que esté bien cocida y jugosa; voltea a la mitad.","Reposa 5 minutos antes de servir.","Pela el ñame, córtalo en trozos y hiérvelo 20 minutos con una pizca de sal hasta que un tenedor lo atraviese sin resistencia.","Corta el pimentón y la cebolla en tiras y saltéalos 6 minutos con una cucharadita de aceite hasta que estén dorados.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','cerdo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-lomo-de-cerdo-magro-guisada-con-champinones-y-cebolla-larga-con-quinua-y-ensalada-de-repollo-y-zanahoria','Lomo de cerdo magro guisada con champiñones y cebolla larga con quinua y ensalada de repollo y zanahoria','lunch','cerdo','cerdo',45,537,49.6,47.1,17,9.2,'[{"food":"cerdo","g":145,"role":"protein","label":"cocida"},{"food":"champi","g":60,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"quinua","g":150,"role":"carb"},{"food":"repollo","g":100,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"limon","g":10,"role":"fixed"}]'::jsonb,'["Sofríe cebolla larga picada y ajo con 1 cucharadita de aceite 3 minutos.","Agrega lomo de cerdo magro en cubos y sella 4 minutos; suma los champiñones laminados y medio vaso de agua.","Tapa y cocina a fuego bajo 15 minutos hasta que espese y la carne esté totalmente cocida.","Enjuaga la quinua, cuécela con el doble de agua 15 minutos y deja reposar tapada 5 minutos.","Ralla el repollo y la zanahoria, aliña con jugo de limón, sal y una cucharadita de aceite de oliva.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','cerdo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-lomo-de-cerdo-magro-en-brocheta-con-pimenton-y-cebolla-con-yuca-cocida-y-pure-de-ahuyama','Lomo de cerdo magro en brocheta con pimentón y cebolla con yuca cocida y puré de ahuyama','lunch','cerdo','cerdo',50,563,43.2,66.3,14.4,6,'[{"food":"cerdo","g":145,"role":"protein","label":"cocida"},{"food":"pimenton","g":50,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"yuca","g":120,"role":"carb"},{"food":"ahuyama","g":150,"role":"veg"}]'::jsonb,'["Corta lomo de cerdo magro en cubos de 3 cm y alterna en palitos con tiras de pimentón y cebolla.","Sazona con sal, ajo, comino y limón.","Asa en sartén o parrilla 12–15 minutos girando para que se cocine por todos los lados.","Pela la yuca, pártela en trozos y hiérvela con sal 20–25 minutos hasta que esté blanda; retira el hilo central.","Cocina la ahuyama en trozos 15 minutos, escúrrela y aplástala con sal y una pizca de comino.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','cerdo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
