insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-pechuga-de-pavo-al-horno-con-hierbas-con-platano-maduro-al-horno-y-habichuela-y-zanahoria-salteadas','Pechuga de pavo al horno con hierbas con plátano maduro al horno y habichuela y zanahoria salteadas','lunch','pavo','pollo',50,392.9,42.2,43.8,7.1,6.6,'[{"food":"pavo","g":130,"role":"protein","label":"cocida"},{"food":"aceite","g":5,"role":"fat"},{"food":"limon","g":10,"role":"fixed"},{"food":"platano_maduro","g":100,"role":"carb"},{"food":"habichuela","g":90,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"}]'::jsonb,'["Calienta el horno a 200 °C. Sazona pechuga de pavo con ajo, tomillo, orégano, sal y limón.","Hornea 20–25 minutos hasta que esté bien cocida y jugosa; voltea a la mitad.","Reposa 5 minutos antes de servir.","Corta el plátano maduro en tajadas, rocíalas con apenas una gota de aceite y hornéalas a 200 °C por 15 minutos, volteando a la mitad.","Saltea la habichuela y la zanahoria en juliana con cebolla larga y 1 cucharadita de aceite 6 minutos; deben quedar tiernas pero crujientes.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','pavo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-pechuga-de-pavo-guisada-con-champinones-y-cebolla-larga-con-arroz-blanco-y-calabacin-salteado','Pechuga de pavo guisada con champiñones y cebolla larga con arroz blanco y calabacín salteado','lunch','pavo','pollo',45,482.7,47.4,54.8,7.5,3.8,'[{"food":"pavo","g":130,"role":"protein","label":"cocida"},{"food":"champi","g":60,"role":"veg"},{"food":"cebolla","g":60,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"arroz","g":150,"role":"carb"},{"food":"calabacin","g":160,"role":"veg"}]'::jsonb,'["Sofríe cebolla larga picada y ajo con 1 cucharadita de aceite 3 minutos.","Agrega pechuga de pavo en cubos y sella 4 minutos; suma los champiñones laminados y medio vaso de agua.","Tapa y cocina a fuego bajo 15 minutos hasta que espese y la carne esté totalmente cocida.","Cocina el arroz con el doble de agua, una pizca de sal y tapa a fuego bajo 18 minutos; suelta con un tenedor.","Corta el calabacín en medias lunas y saltéalo con cebolla 5 minutos a fuego alto para que no suelte agua.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','pavo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-pechuga-de-pavo-en-brocheta-con-pimenton-y-cebolla-con-name-cocido-y-espinacas-con-champinones','Pechuga de pavo en brocheta con pimentón y cebolla con ñame cocido y espinacas con champiñones','lunch','pavo','pollo',45,424,45.8,44.7,7.2,8.9,'[{"food":"pavo","g":130,"role":"protein","label":"cocida"},{"food":"pimenton","g":50,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"name","g":120,"role":"carb"},{"food":"espinaca","g":80,"role":"veg"},{"food":"champi","g":60,"role":"veg"}]'::jsonb,'["Corta pechuga de pavo en cubos de 3 cm y alterna en palitos con tiras de pimentón y cebolla.","Sazona con sal, ajo, comino y limón.","Asa en sartén o parrilla 12–15 minutos girando para que se cocine por todos los lados.","Pela el ñame, córtalo en trozos y hiérvelo 20 minutos con una pizca de sal hasta que un tenedor lo atraviese sin resistencia.","Saltea los champiñones laminados con ajo 4 minutos, añade la espinaca y cocina 2 minutos hasta que se marchite.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','pavo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-albondigas-de-carne-molida-magra-al-horno-con-quinua-y-pimenton-y-cebolla-salteados','Albóndigas de carne molida magra al horno con quinua y pimentón y cebolla salteados','lunch','res','res',50,524,50.9,43.7,15.2,7.2,'[{"food":"molida","g":150,"role":"protein","label":"cocida"},{"food":"cebolla","g":80,"role":"veg"},{"food":"clara","g":33,"role":"protein"},{"food":"quinua","g":150,"role":"carb"},{"food":"pimenton","g":80,"role":"veg"}]'::jsonb,'["Mezcla carne molida magra con cebolla rallada, ajo, sal, comino y 1 clara; forma bolitas de 4 cm.","Hornea a 200 °C por 18–20 minutos, volteando a la mitad, hasta que estén cocidas por dentro (sin rosado).","Sirve calientes.","Enjuaga la quinua, cuécela con el doble de agua 15 minutos y deja reposar tapada 5 minutos.","Corta el pimentón y la cebolla en tiras y saltéalos 6 minutos con una cucharadita de aceite hasta que estén dorados.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','res','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-carne-molida-magra-salteada-con-zanahoria-y-cebolla-con-yuca-cocida-y-ensalada-de-repollo-y-zanahoria','Carne molida magra salteada con zanahoria y cebolla con yuca cocida y ensalada de repollo y zanahoria','lunch','res','res',40,580.9,43.2,62.9,17.7,7.9,'[{"food":"molida","g":150,"role":"protein","label":"cocida"},{"food":"cebolla","g":40,"role":"veg"},{"food":"zanahoria","g":90,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"yuca","g":120,"role":"carb"},{"food":"repollo","g":100,"role":"veg"},{"food":"limon","g":10,"role":"fixed"}]'::jsonb,'["Sofríe cebolla y zanahoria rallada con 1 cucharadita de aceite 4 minutos.","Agrega carne molida magra, sazona con comino y sal, y cocina 10 minutos desbaratando los grumos hasta que esté bien cocida.","Pela la yuca, pártela en trozos y hiérvela con sal 20–25 minutos hasta que esté blanda; retira el hilo central.","Ralla el repollo y la zanahoria, aliña con jugo de limón, sal y una cucharadita de aceite de oliva.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','res','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-mini-pastel-de-carne-molida-magra-con-espinaca-con-papa-criolla-y-pure-de-ahuyama','Mini pastel de carne molida magra con espinaca con papa criolla y puré de ahuyama','lunch','res','res',48,472.7,48.4,41.4,12.5,6.4,'[{"food":"molida","g":150,"role":"protein","label":"cocida"},{"food":"espinaca","g":50,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"clara","g":33,"role":"protein"},{"food":"papa_criolla","g":120,"role":"carb"},{"food":"ahuyama","g":150,"role":"veg"}]'::jsonb,'["Calienta el horno a 190 °C.","Mezcla carne molida magra con espinaca picada, cebolla, 1 clara, sal y comino.","Llena moldes de muffin y hornea 22 minutos hasta que estén firmes y cocidos por dentro.","Hierve las papas criollas con cáscara y sal 15 minutos; escurre y sirve.","Cocina la ahuyama en trozos 15 minutos, escúrrela y aplástala con sal y una pizca de comino.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','res','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-bocachico-a-la-plancha-con-limon-con-arroz-integral-y-ensalada-de-lechuga-y-aguacate','Bocachico a la plancha con limón con arroz integral y ensalada de lechuga y aguacate','lunch','bocachico','pescado',45,547.1,45.2,45.5,21.1,6.4,'[{"food":"bocachico","g":170,"role":"protein","label":"cocida"},{"food":"aceite","g":5,"role":"fat"},{"food":"limon","g":20,"role":"fixed"},{"food":"arroz_int","g":150,"role":"carb"},{"food":"lechuga","g":80,"role":"veg"},{"food":"aguacate","g":40,"role":"fat"}]'::jsonb,'["Sazona el filete de bocachico con sal, ajo y limón.","Cocina en sartén antiadherente con 1 cucharadita de aceite, 4–5 minutos por lado, hasta que la carne se desmenuce con el tenedor y no quede translúcida.","Cocina el arroz integral con 2,5 partes de agua a fuego bajo y tapado por 35 minutos; deja reposar 5.","Lava bien la lechuga, trocéala y mezcla con el aguacate en cubos, limón y sal.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','bocachico','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-bocachico-al-horno-con-cebolla-y-pimenton-con-platano-maduro-al-horno-y-berenjena-al-horno','Bocachico al horno con cebolla y pimentón con plátano maduro al horno y berenjena al horno','lunch','bocachico','pescado',47,485.1,42.1,51.1,14.4,7.6,'[{"food":"bocachico","g":170,"role":"protein","label":"cocida"},{"food":"cebolla","g":40,"role":"veg"},{"food":"pimenton","g":40,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"platano_maduro","g":100,"role":"carb"},{"food":"berenjena","g":150,"role":"veg"}]'::jsonb,'["Calienta el horno a 200 °C. Pon el filete de bocachico sobre cebolla y pimentón en tiras.","Sazona con sal, ajo, comino y limón; cubre con papel aluminio.","Hornea 20 minutos hasta que esté completamente cocido y opaco.","Corta el plátano maduro en tajadas, rocíalas con apenas una gota de aceite y hornéalas a 200 °C por 15 minutos, volteando a la mitad.","Corta la berenjena en rodajas, sazona con sal, ajo y comino y hornea a 200 °C por 20 minutos.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','bocachico','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-bocachico-en-salsa-de-coco-ligera-con-arroz-blanco-y-habichuela-y-zanahoria-salteadas','Bocachico en salsa de coco ligera con arroz blanco y habichuela y zanahoria salteadas','lunch','bocachico','pescado',40,524,45.9,56.6,12.3,5.4,'[{"food":"bocachico","g":170,"role":"protein","label":"cocida"},{"food":"coco","g":25,"role":"fat"},{"food":"cebolla","g":30,"role":"veg"},{"food":"arroz","g":150,"role":"carb"},{"food":"habichuela","g":90,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"}]'::jsonb,'["Sofríe cebolla larga y ajo con una cucharadita de aceite 3 minutos.","Agrega la leche de coco light, sal y comino; cuando hierva, añade el filete de bocachico.","Tapa y cocina a fuego bajo 10–12 minutos hasta que esté bien cocido.","Cocina el arroz con el doble de agua, una pizca de sal y tapa a fuego bajo 18 minutos; suelta con un tenedor.","Saltea la habichuela y la zanahoria en juliana con cebolla larga y 1 cucharadita de aceite 6 minutos; deben quedar tiernas pero crujientes.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','bocachico','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
