insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-mojarra-a-la-plancha-con-limon-con-quinua-y-espinacas-con-champinones','Mojarra a la plancha con limón con quinua y espinacas con champiñones','lunch','mojarra','pescado',30,456.6,49.8,37.6,12.4,6.7,'[{"food":"mojarra","g":150,"role":"protein","label":"cocida"},{"food":"aceite","g":5,"role":"fat"},{"food":"limon","g":10,"role":"fixed"},{"food":"quinua","g":150,"role":"carb"},{"food":"espinaca","g":80,"role":"veg"},{"food":"champi","g":60,"role":"veg"}]'::jsonb,'["Sazona el filete de mojarra con sal, ajo y limón.","Cocina en sartén antiadherente con 1 cucharadita de aceite, 4–5 minutos por lado, hasta que la carne se desmenuce con el tenedor y no quede translúcida.","Enjuaga la quinua, cuécela con el doble de agua 15 minutos y deja reposar tapada 5 minutos.","Saltea los champiñones laminados con ajo 4 minutos, añade la espinaca y cocina 2 minutos hasta que se marchite.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','mojarra','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-mojarra-al-horno-con-cebolla-y-pimenton-con-yuca-cocida-y-pimenton-y-cebolla-salteados','Mojarra al horno con cebolla y pimentón con yuca cocida y pimentón y cebolla salteados','lunch','mojarra','pescado',50,504.4,42.9,60.9,9.9,6.2,'[{"food":"mojarra","g":150,"role":"protein","label":"cocida"},{"food":"cebolla","g":90,"role":"veg"},{"food":"pimenton","g":120,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"yuca","g":120,"role":"carb"}]'::jsonb,'["Calienta el horno a 200 °C. Pon el filete de mojarra sobre cebolla y pimentón en tiras.","Sazona con sal, ajo, comino y limón; cubre con papel aluminio.","Hornea 20 minutos hasta que esté completamente cocido y opaco.","Pela la yuca, pártela en trozos y hiérvela con sal 20–25 minutos hasta que esté blanda; retira el hilo central.","Corta el pimentón y la cebolla en tiras y saltéalos 6 minutos con una cucharadita de aceite hasta que estén dorados.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','mojarra','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-mojarra-en-salsa-de-coco-ligera-con-papa-criolla-y-ensalada-de-repollo-y-zanahoria','Mojarra en salsa de coco ligera con papa criolla y ensalada de repollo y zanahoria','lunch','mojarra','pescado',35,383.7,43.8,35.6,7.4,6.8,'[{"food":"mojarra","g":150,"role":"protein","label":"cocida"},{"food":"coco","g":25,"role":"fat"},{"food":"cebolla","g":30,"role":"veg"},{"food":"papa_criolla","g":120,"role":"carb"},{"food":"repollo","g":100,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"limon","g":10,"role":"fixed"}]'::jsonb,'["Sofríe cebolla larga y ajo con una cucharadita de aceite 3 minutos.","Agrega la leche de coco light, sal y comino; cuando hierva, añade el filete de mojarra.","Tapa y cocina a fuego bajo 10–12 minutos hasta que esté bien cocido.","Hierve las papas criollas con cáscara y sal 15 minutos; escurre y sirve.","Ralla el repollo y la zanahoria, aliña con jugo de limón, sal y una cucharadita de aceite de oliva.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','mojarra','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-mojarra-en-papillote-con-limon-y-cilantro-con-arroz-integral-y-pure-de-ahuyama','Mojarra en papillote con limón y cilantro con arroz integral y puré de ahuyama','lunch','mojarra','pescado',55,487,44.6,54.5,10.7,5,'[{"food":"mojarra","g":150,"role":"protein","label":"cocida"},{"food":"limon","g":15,"role":"fixed"},{"food":"aceite","g":5,"role":"fat"},{"food":"arroz_int","g":150,"role":"carb"},{"food":"ahuyama","g":150,"role":"veg"}]'::jsonb,'["Pon el filete de mojarra sobre papel aluminio con rodajas de limón, cilantro, ajo y sal.","Cierra el paquete y hornea a 200 °C por 18–20 minutos hasta que esté bien cocido.","Cocina el arroz integral con 2,5 partes de agua a fuego bajo y tapado por 35 minutos; deja reposar 5.","Cocina la ahuyama en trozos 15 minutos, escúrrela y aplástala con sal y una pizca de comino.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','mojarra','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-robalo-a-la-plancha-con-limon-con-platano-maduro-al-horno-y-ensalada-de-lechuga-y-aguacate','Róbalo a la plancha con limón con plátano maduro al horno y ensalada de lechuga y aguacate','lunch','robalo','pescado',30,459.1,42.1,39.1,15.7,6,'[{"food":"robalo","g":170,"role":"protein","label":"cocida"},{"food":"aceite","g":5,"role":"fat"},{"food":"limon","g":20,"role":"fixed"},{"food":"platano_maduro","g":100,"role":"carb"},{"food":"lechuga","g":80,"role":"veg"},{"food":"aguacate","g":40,"role":"fat"}]'::jsonb,'["Sazona el filete de róbalo con sal, ajo y limón.","Cocina en sartén antiadherente con 1 cucharadita de aceite, 4–5 minutos por lado, hasta que la carne se desmenuce con el tenedor y no quede translúcida.","Corta el plátano maduro en tajadas, rocíalas con apenas una gota de aceite y hornéalas a 200 °C por 15 minutos, volteando a la mitad.","Lava bien la lechuga, trocéala y mezcla con el aguacate en cubos, limón y sal.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','robalo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-robalo-al-horno-con-cebolla-y-pimenton-con-arroz-blanco-y-berenjena-al-horno','Róbalo al horno con cebolla y pimentón con arroz blanco y berenjena al horno','lunch','robalo','pescado',47,532.6,45.2,61.1,10.2,5.9,'[{"food":"robalo","g":170,"role":"protein","label":"cocida"},{"food":"cebolla","g":40,"role":"veg"},{"food":"pimenton","g":40,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"arroz","g":150,"role":"carb"},{"food":"berenjena","g":150,"role":"veg"}]'::jsonb,'["Calienta el horno a 200 °C. Pon el filete de róbalo sobre cebolla y pimentón en tiras.","Sazona con sal, ajo, comino y limón; cubre con papel aluminio.","Hornea 20 minutos hasta que esté completamente cocido y opaco.","Cocina el arroz con el doble de agua, una pizca de sal y tapa a fuego bajo 18 minutos; suelta con un tenedor.","Corta la berenjena en rodajas, sazona con sal, ajo y comino y hornea a 200 °C por 20 minutos.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','robalo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-robalo-en-salsa-de-coco-ligera-con-name-cocido-y-habichuela-y-zanahoria-salteadas','Róbalo en salsa de coco ligera con ñame cocido y habichuela y zanahoria salteadas','lunch','robalo','pescado',40,445.1,43.6,48.2,7.9,9.6,'[{"food":"robalo","g":170,"role":"protein","label":"cocida"},{"food":"coco","g":25,"role":"fat"},{"food":"cebolla","g":30,"role":"veg"},{"food":"name","g":120,"role":"carb"},{"food":"habichuela","g":90,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"}]'::jsonb,'["Sofríe cebolla larga y ajo con una cucharadita de aceite 3 minutos.","Agrega la leche de coco light, sal y comino; cuando hierva, añade el filete de róbalo.","Tapa y cocina a fuego bajo 10–12 minutos hasta que esté bien cocido.","Pela el ñame, córtalo en trozos y hiérvelo 20 minutos con una pizca de sal hasta que un tenedor lo atraviese sin resistencia.","Saltea la habichuela y la zanahoria en juliana con cebolla larga y 1 cucharadita de aceite 6 minutos; deben quedar tiernas pero crujientes.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','robalo','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
