insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-camarones-salteados-al-ajo-con-limon-con-arroz-blanco-y-ensalada-de-lechuga-y-aguacate','Camarones salteados al ajo con limón con arroz blanco y ensalada de lechuga y aguacate','lunch','camaron','camaron',27,484.6,45.6,49.4,12,4.3,'[{"food":"camaron","g":165,"role":"protein","label":"cocida"},{"food":"aceite","g":5,"role":"fat"},{"food":"limon","g":20,"role":"fixed"},{"food":"arroz","g":150,"role":"carb"},{"food":"lechuga","g":80,"role":"veg"},{"food":"aguacate","g":40,"role":"fat"}]'::jsonb,'["Sazona los camarones limpios con sal y limón.","Saltea ajo picado en 1 cucharadita de aceite 30 segundos; añade los camarones y cocina 3–4 minutos hasta que estén bien rosados y firmes.","Cocina el arroz con el doble de agua, una pizca de sal y tapa a fuego bajo 18 minutos; suelta con un tenedor.","Lava bien la lechuga, trocéala y mezcla con el aguacate en cubos, limón y sal.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','camaron','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-camarones-en-salsa-de-coco-con-name-cocido-y-berenjena-al-horno','Camarones en salsa de coco con ñame cocido y berenjena al horno','lunch','camaron','camaron',32,401.1,43.2,50.4,4.1,9.1,'[{"food":"camaron","g":165,"role":"protein","label":"cocida"},{"food":"coco","g":25,"role":"fat"},{"food":"cebolla","g":30,"role":"veg"},{"food":"name","g":120,"role":"carb"},{"food":"berenjena","g":150,"role":"veg"}]'::jsonb,'["Sofríe cebolla y ajo con 1 cucharadita de aceite 3 minutos.","Agrega leche de coco light y sal; cuando hierva, añade los camarones y cocina 5 minutos hasta que estén completamente cocidos.","Pela el ñame, córtalo en trozos y hiérvelo 20 minutos con una pizca de sal hasta que un tenedor lo atraviese sin resistencia.","Corta la berenjena en rodajas, sazona con sal, ajo y comino y hornea a 200 °C por 20 minutos.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','camaron','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('lunch-camarones-salteados-con-pimenton-y-cebolla-con-quinua-y-habichuela-y-zanahoria-salteadas','Camarones salteados con pimentón y cebolla con quinua y habichuela y zanahoria salteadas','lunch','camaron','camaron',30,465.7,49.1,48.6,8.9,10,'[{"food":"camaron","g":165,"role":"protein","label":"cocida"},{"food":"pimenton","g":50,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"quinua","g":150,"role":"carb"},{"food":"habichuela","g":90,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"}]'::jsonb,'["Saltea cebolla y pimentón en tiras con 1 cucharadita de aceite 4 minutos.","Agrega los camarones sazonados con comino y sal; cocina 4 minutos más hasta que estén firmes y rosados.","Enjuaga la quinua, cuécela con el doble de agua 15 minutos y deja reposar tapada 5 minutos.","Saltea la habichuela y la zanahoria en juliana con cebolla larga y 1 cucharadita de aceite 6 minutos; deben quedar tiernas pero crujientes.","Arma el plato: la proteína ocupa un cuarto, el carbohidrato otro cuarto y la mitad del plato son verduras. Mide las porciones con la balanza o con las medidas caseras indicadas."]'::jsonb,array['almuerzo','camaron','colombiana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-omelette-de-claras-con-espinaca-y-champinones','Omelette de claras con espinaca y champiñones','dinner','huevo','huevo',15,262.7,28.6,7.3,13.6,2.5,'[{"food":"huevo","g":50,"role":"protein"},{"food":"clara","g":132,"role":"protein"},{"food":"espinaca","g":80,"role":"veg"},{"food":"champi","g":60,"role":"veg"},{"food":"campesino","g":20,"role":"protein"},{"food":"aceite","g":4,"role":"fat"}]'::jsonb,'["Saltea champiñones y espinaca con ajo 4 minutos y reserva.","Bate el huevo con las claras y sal; cuaja en sartén antiadherente con el aceite a fuego medio-bajo.","Rellena con las verduras y el queso campesino pasteurizado, dobla y cocina hasta que el huevo esté completamente firme."]'::jsonb,array['cena','huevo','plato de la casa','rápido']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-tortilla-de-huevo-con-ahuyama-y-cebolla','Tortilla de huevo con ahuyama y cebolla','dinner','huevo','huevo',20,284.2,22.3,15.7,15.4,2.7,'[{"food":"huevo","g":100,"role":"protein"},{"food":"clara","g":66,"role":"protein"},{"food":"ahuyama","g":100,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"aceite","g":4,"role":"fat"},{"food":"lechuga","g":50,"role":"veg"}]'::jsonb,'["Cuece la ahuyama en cubos pequeños 8 minutos.","Sofríe la cebolla, añade la ahuyama y vierte los huevos batidos con sal.","Tapa a fuego bajo 6–8 minutos y voltea para que quede firme por ambos lados. Sirve con lechuga."]'::jsonb,array['cena','huevo','plato de la casa','vegetariana']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-crema-de-ahuyama-con-pollo-desmechado','Crema de ahuyama con pollo desmechado','dinner','pollo','sopa',30,344.5,38.3,27.7,9.1,3.5,'[{"food":"ahuyama","g":200,"role":"veg"},{"food":"pechuga","g":105,"role":"protein","label":"desmechada"},{"food":"cebolla","g":30,"role":"veg"},{"food":"leche","g":100,"role":"fixed"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Cuece la ahuyama con cebolla y ajo 15 minutos y licúa con la leche y sal hasta obtener una crema.","Cuece y desmecha la pechuga.","Sirve la crema caliente con el pollo encima."]'::jsonb,array['cena','pollo','plato de la casa','sopa']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-sopa-de-pollo-con-verduras','Sopa de pollo con verduras','dinner','pollo','sopa',35,278.3,35.7,23,4.2,5.3,'[{"food":"pechuga","g":105,"role":"protein"},{"food":"zanahoria","g":60,"role":"veg"},{"food":"habichuela","g":60,"role":"veg"},{"food":"papa_criolla","g":60,"role":"carb"},{"food":"cebolla","g":30,"role":"veg"}]'::jsonb,'["Hierve la pechuga 15 minutos con cebolla, ajo y sal; retira y desmecha.","Cuece zanahoria, habichuela y papa criolla en el caldo 12 minutos.","Devuelve el pollo y sirve caliente."]'::jsonb,array['cena','pollo','plato de la casa','sopa']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-ensalada-de-atun-con-aguacate-y-lechuga','Ensalada de atún con aguacate y lechuga','dinner','atun','atun',15,339.2,39.4,12.8,15.8,6.4,'[{"food":"atun","g":115,"role":"protein"},{"food":"aguacate","g":60,"role":"fat"},{"food":"lechuga","g":100,"role":"veg"},{"food":"zanahoria","g":40,"role":"veg"},{"food":"limon","g":15,"role":"fixed"},{"food":"huevo","g":50,"role":"protein","label":"duro"}]'::jsonb,'["Cuece el huevo 10 minutos hasta que la yema esté firme; pela y pica.","Escurre el atún y mezcla con lechuga, zanahoria rallada y aguacate.","Aliña con limón, sal y una pizca de orégano."]'::jsonb,array['cena','atun','plato de la casa','rápido','frío']::text[],0,'El atún en lata va limitado a 1–2 porciones por semana en el embarazo.') on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
