insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-berenjena-rellena-de-carne-y-queso-campesino','Berenjena rellena de carne y queso campesino','dinner','res','res',40,375.4,34.3,20.7,17.9,5.5,'[{"food":"berenjena","g":200,"role":"veg"},{"food":"molida","g":105,"role":"protein"},{"food":"campesino","g":30,"role":"protein"},{"food":"cebolla","g":30,"role":"veg"},{"food":"aceite","g":4,"role":"fat"}]'::jsonb,'["Parte la berenjena por la mitad, vacía un poco el centro y hornéala 15 minutos a 200 °C.","Sofríe cebolla y la carne molida con sal y comino 8 minutos hasta que esté bien cocida; mezcla con la pulpa picada.","Rellena, cubre con queso campesino pasteurizado y gratina 8 minutos."]'::jsonb,array['cena','res','plato de la casa','horno']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
