insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-pechuga-rellena-de-espinaca-y-queso-campesino','Pechuga rellena de espinaca y queso campesino','dinner','pollo','pollo',35,288.9,39.4,4.5,12.3,2.2,'[{"food":"pechuga","g":105,"role":"protein"},{"food":"espinaca","g":60,"role":"veg"},{"food":"campesino","g":25,"role":"protein"},{"food":"lechuga","g":60,"role":"veg"},{"food":"aceite","g":4,"role":"fat"}]'::jsonb,'["Abre la pechuga en libro y sazona con sal y ajo.","Rellena con espinaca salteada y queso campesino pasteurizado; ciérrala con palillos.","Hornea a 200 °C por 25 minutos hasta que esté completamente cocida. Sirve con lechuga."]'::jsonb,array['cena','pollo','plato de la casa','horno']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-sopa-de-lentejas-con-espinaca-y-huevo-duro','Sopa de lentejas con espinaca y huevo duro','dinner','legumbre','legumbre',35,366.5,31.4,26.5,15.7,9.9,'[{"food":"lentejas","g":100,"role":"fixed"},{"food":"huevo","g":100,"role":"protein","label":"duro"},{"food":"clara","g":66,"role":"protein"},{"food":"espinaca","g":60,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"aceite","g":4,"role":"fat"}]'::jsonb,'["Cuece las lentejas con cebolla y ajo 20 minutos.","Agrega la espinaca los últimos 3 minutos.","Sirve con el huevo y las claras cocidas (10 minutos) en cuartos."]'::jsonb,array['cena','legumbre','plato de la casa','hierro','folato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-pechuga-de-pollo-a-la-plancha-con-ajo-y-limon-con-pure-de-ahuyama-y-ensalada-de-repollo-y-zanahoria','Pechuga de pollo a la plancha con ajo y limón con puré de ahuyama y ensalada de repollo y zanahoria','dinner','pollo','pollo',28,422.4,36.3,45.8,11.9,10.6,'[{"food":"pechuga","g":98,"role":"protein","label":"cocida"},{"food":"limon","g":20,"role":"fixed"},{"food":"ahuyama","g":150,"role":"veg"},{"food":"repollo","g":100,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"aguacate","g":50,"role":"fat"},{"food":"arroz_int","g":60,"role":"carb"}]'::jsonb,'["Sazona pechuga de pollo con ajo, comino, sal y jugo de limón; déjala reposar 15 minutos.","Sella en una sartén antiadherente con 1 cucharadita de aceite, 5–6 minutos por lado hasta que esté completamente cocida (temperatura interna de 74 °C si usas termómetro); sin partes rosadas por dentro.","Deja reposar 3 minutos antes de cortar en tiras.","Cocina la ahuyama en trozos 15 minutos, escúrrela y aplástala con sal y una pizca de comino.","Ralla el repollo y la zanahoria, aliña con jugo de limón, sal y una cucharadita de aceite de oliva.","Sirve con una porción pequeña de arroz integral cocido (cena baja en carbohidrato)."]'::jsonb,array['cena','pollo','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-pechuga-de-pollo-desmechada-con-cebolla-y-pimenton-con-espinacas-con-champinones-y-calabacin-salteado','Pechuga de pollo desmechada con cebolla y pimentón con espinacas con champiñones y calabacín salteado','dinner','pollo','pollo',48,308.7,37.7,19.1,9.7,6.2,'[{"food":"pechuga","g":98,"role":"protein","label":"cocida"},{"food":"cebolla","g":70,"role":"veg"},{"food":"pimenton","g":40,"role":"veg"},{"food":"espinaca","g":80,"role":"veg"},{"food":"champi","g":60,"role":"veg"},{"food":"calabacin","g":160,"role":"veg"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Hierve pechuga de pollo en agua con cebolla, ajo y sal 25 minutos hasta que esté muy tierna.","Desmecha con dos tenedores.","Sofríe cebolla y pimentón en tiras con 1 cucharadita de aceite 5 minutos, agrega la carne desmechada y cocina 5 minutos más.","Saltea los champiñones laminados con ajo 4 minutos, añade la espinaca y cocina 2 minutos hasta que se marchite.","Corta el calabacín en medias lunas y saltéalo con cebolla 5 minutos a fuego alto para que no suelte agua.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','pollo','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-pechuga-de-pollo-al-horno-con-hierbas-con-berenjena-al-horno-y-ensalada-de-lechuga-y-aguacate','Pechuga de pollo al horno con hierbas con berenjena al horno y ensalada de lechuga y aguacate','dinner','pollo','pollo',43,310.6,33.8,21,11.4,8.1,'[{"food":"pechuga","g":98,"role":"protein","label":"cocida"},{"food":"limon","g":20,"role":"fixed"},{"food":"berenjena","g":150,"role":"veg"},{"food":"lechuga","g":80,"role":"veg"},{"food":"aguacate","g":50,"role":"fat"}]'::jsonb,'["Calienta el horno a 200 °C. Sazona pechuga de pollo con ajo, tomillo, orégano, sal y limón.","Hornea 20–25 minutos hasta que esté bien cocida y jugosa; voltea a la mitad.","Reposa 5 minutos antes de servir.","Corta la berenjena en rodajas, sazona con sal, ajo y comino y hornea a 200 °C por 20 minutos.","Lava bien la lechuga, trocéala y mezcla con el aguacate en cubos, limón y sal.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','pollo','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-muslo-de-pollo-sin-piel-desmechada-con-cebolla-y-pimenton-con-ensalada-de-repollo-y-zanahoria-y-pimenton-y-cebolla-salteados','Muslo de pollo sin piel desmechada con cebolla y pimentón con ensalada de repollo y zanahoria y pimentón y cebolla salteados','dinner','pollo','pollo',48,365.1,34.1,25.8,14.9,8,'[{"food":"muslo","g":116,"role":"protein","label":"cocida"},{"food":"cebolla","g":90,"role":"veg"},{"food":"pimenton","g":120,"role":"veg"},{"food":"repollo","g":100,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"limon","g":10,"role":"fixed"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Hierve muslo de pollo sin piel en agua con cebolla, ajo y sal 25 minutos hasta que esté muy tierna.","Desmecha con dos tenedores.","Sofríe cebolla y pimentón en tiras con 1 cucharadita de aceite 5 minutos, agrega la carne desmechada y cocina 5 minutos más.","Ralla el repollo y la zanahoria, aliña con jugo de limón, sal y una cucharadita de aceite de oliva.","Corta el pimentón y la cebolla en tiras y saltéalos 6 minutos con una cucharadita de aceite hasta que estén dorados.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','pollo','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-muslo-de-pollo-sin-piel-al-horno-con-hierbas-con-calabacin-salteado-y-habichuela-y-zanahoria-salteadas','Muslo de pollo sin piel al horno con hierbas con calabacín salteado y habichuela y zanahoria salteadas','dinner','pollo','pollo',43,373.4,35.6,23.7,17.5,9.7,'[{"food":"muslo","g":116,"role":"protein","label":"cocida"},{"food":"limon","g":10,"role":"fixed"},{"food":"calabacin","g":160,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"habichuela","g":90,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"aguacate","g":50,"role":"fat"}]'::jsonb,'["Calienta el horno a 200 °C. Sazona muslo de pollo sin piel con ajo, tomillo, orégano, sal y limón.","Hornea 20–25 minutos hasta que esté bien cocida y jugosa; voltea a la mitad.","Reposa 5 minutos antes de servir.","Corta el calabacín en medias lunas y saltéalo con cebolla 5 minutos a fuego alto para que no suelte agua.","Saltea la habichuela y la zanahoria en juliana con cebolla larga y 1 cucharadita de aceite 6 minutos; deben quedar tiernas pero crujientes.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','pollo','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-muslo-de-pollo-sin-piel-guisada-con-champinones-y-cebolla-larga-con-ensalada-de-lechuga-y-aguacate-y-pure-de-ahuyama','Muslo de pollo sin piel guisada con champiñones y cebolla larga con ensalada de lechuga y aguacate y puré de ahuyama','dinner','pollo','pollo',38,424,36.6,38.5,15.5,5.5,'[{"food":"muslo","g":116,"role":"protein","label":"cocida"},{"food":"champi","g":60,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"lechuga","g":80,"role":"veg"},{"food":"limon","g":10,"role":"fixed"},{"food":"ahuyama","g":150,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"arroz_int","g":60,"role":"carb"}]'::jsonb,'["Sofríe cebolla larga picada y ajo con 1 cucharadita de aceite 3 minutos.","Agrega muslo de pollo sin piel en cubos y sella 4 minutos; suma los champiñones laminados y medio vaso de agua.","Tapa y cocina a fuego bajo 15 minutos hasta que espese y la carne esté totalmente cocida.","Lava bien la lechuga, trocéala y mezcla con el aguacate en cubos, limón y sal.","Cocina la ahuyama en trozos 15 minutos, escúrrela y aplástala con sal y una pizca de comino.","Sirve con una porción pequeña de arroz integral cocido (cena baja en carbohidrato)."]'::jsonb,array['cena','pollo','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-res-magra-al-horno-con-hierbas-con-pimenton-y-cebolla-salteados-y-espinacas-con-champinones','Res magra al horno con hierbas con pimentón y cebolla salteados y espinacas con champiñones','dinner','res','res',43,361.7,37,19.7,16.5,8.4,'[{"food":"res","g":105,"role":"protein","label":"cocida"},{"food":"limon","g":10,"role":"fixed"},{"food":"pimenton","g":80,"role":"veg"},{"food":"cebolla","g":50,"role":"veg"},{"food":"espinaca","g":80,"role":"veg"},{"food":"champi","g":60,"role":"veg"},{"food":"aguacate","g":50,"role":"fat"}]'::jsonb,'["Calienta el horno a 200 °C. Sazona res magra con ajo, tomillo, orégano, sal y limón.","Hornea 20–25 minutos hasta que esté bien cocida y jugosa; voltea a la mitad.","Reposa 5 minutos antes de servir.","Corta el pimentón y la cebolla en tiras y saltéalos 6 minutos con una cucharadita de aceite hasta que estén dorados.","Saltea los champiñones laminados con ajo 4 minutos, añade la espinaca y cocina 2 minutos hasta que se marchite.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','res','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-res-magra-guisada-con-champinones-y-cebolla-larga-con-habichuela-y-zanahoria-salteadas-y-berenjena-al-horno','Res magra guisada con champiñones y cebolla larga con habichuela y zanahoria salteadas y berenjena al horno','dinner','res','res',38,447.8,37.5,44.6,14.9,10.2,'[{"food":"res","g":105,"role":"protein","label":"cocida"},{"food":"champi","g":60,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"habichuela","g":90,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"berenjena","g":150,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"arroz_int","g":60,"role":"carb"}]'::jsonb,'["Sofríe cebolla larga picada y ajo con 1 cucharadita de aceite 3 minutos.","Agrega res magra en cubos y sella 4 minutos; suma los champiñones laminados y medio vaso de agua.","Tapa y cocina a fuego bajo 15 minutos hasta que espese y la carne esté totalmente cocida.","Saltea la habichuela y la zanahoria en juliana con cebolla larga y 1 cucharadita de aceite 6 minutos; deben quedar tiernas pero crujientes.","Corta la berenjena en rodajas, sazona con sal, ajo y comino y hornea a 200 °C por 20 minutos.","Sirve con una porción pequeña de arroz integral cocido (cena baja en carbohidrato)."]'::jsonb,array['cena','res','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-res-magra-en-brocheta-con-pimenton-y-cebolla-con-pure-de-ahuyama-y-ensalada-de-repollo-y-zanahoria','Res magra en brocheta con pimentón y cebolla con puré de ahuyama y ensalada de repollo y zanahoria','dinner','res','res',38,411.7,35.5,35.5,16.3,11.1,'[{"food":"res","g":105,"role":"protein","label":"cocida"},{"food":"pimenton","g":50,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"ahuyama","g":150,"role":"veg"},{"food":"repollo","g":100,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"limon","g":10,"role":"fixed"},{"food":"aguacate","g":50,"role":"fat"}]'::jsonb,'["Corta res magra en cubos de 3 cm y alterna en palitos con tiras de pimentón y cebolla.","Sazona con sal, ajo, comino y limón.","Asa en sartén o parrilla 12–15 minutos girando para que se cocine por todos los lados.","Cocina la ahuyama en trozos 15 minutos, escúrrela y aplástala con sal y una pizca de comino.","Ralla el repollo y la zanahoria, aliña con jugo de limón, sal y una cucharadita de aceite de oliva.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','res','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-lomo-de-cerdo-magro-guisada-con-champinones-y-cebolla-larga-con-espinacas-con-champinones-y-calabacin-salteado','Lomo de cerdo magro guisada con champiñones y cebolla larga con espinacas con champiñones y calabacín salteado','dinner','cerdo','cerdo',38,401.1,39.6,33.6,13.4,6.8,'[{"food":"cerdo","g":109,"role":"protein","label":"cocida"},{"food":"champi","g":120,"role":"veg"},{"food":"cebolla","g":60,"role":"veg"},{"food":"espinaca","g":80,"role":"veg"},{"food":"calabacin","g":160,"role":"veg"},{"food":"aceite","g":5,"role":"fat"},{"food":"arroz_int","g":60,"role":"carb"}]'::jsonb,'["Sofríe cebolla larga picada y ajo con 1 cucharadita de aceite 3 minutos.","Agrega lomo de cerdo magro en cubos y sella 4 minutos; suma los champiñones laminados y medio vaso de agua.","Tapa y cocina a fuego bajo 15 minutos hasta que espese y la carne esté totalmente cocida.","Saltea los champiñones laminados con ajo 4 minutos, añade la espinaca y cocina 2 minutos hasta que se marchite.","Corta el calabacín en medias lunas y saltéalo con cebolla 5 minutos a fuego alto para que no suelte agua.","Sirve con una porción pequeña de arroz integral cocido (cena baja en carbohidrato)."]'::jsonb,array['cena','cerdo','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-lomo-de-cerdo-magro-en-brocheta-con-pimenton-y-cebolla-con-berenjena-al-horno-y-ensalada-de-lechuga-y-aguacate','Lomo de cerdo magro en brocheta con pimentón y cebolla con berenjena al horno y ensalada de lechuga y aguacate','dinner','cerdo','cerdo',38,354.1,33.6,26,14.6,9.7,'[{"food":"cerdo","g":109,"role":"protein","label":"cocida"},{"food":"pimenton","g":50,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"berenjena","g":150,"role":"veg"},{"food":"lechuga","g":80,"role":"veg"},{"food":"limon","g":10,"role":"fixed"},{"food":"aguacate","g":50,"role":"fat"}]'::jsonb,'["Corta lomo de cerdo magro en cubos de 3 cm y alterna en palitos con tiras de pimentón y cebolla.","Sazona con sal, ajo, comino y limón.","Asa en sartén o parrilla 12–15 minutos girando para que se cocine por todos los lados.","Corta la berenjena en rodajas, sazona con sal, ajo y comino y hornea a 200 °C por 20 minutos.","Lava bien la lechuga, trocéala y mezcla con el aguacate en cubos, limón y sal.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','cerdo','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-lomo-de-cerdo-magro-a-la-plancha-con-ajo-y-limon-con-ensalada-de-repollo-y-zanahoria-y-pimenton-y-cebolla-salteados','Lomo de cerdo magro a la plancha con ajo y limón con ensalada de repollo y zanahoria y pimentón y cebolla salteados','dinner','cerdo','cerdo',28,315.8,32.6,20.5,12.1,6.4,'[{"food":"cerdo","g":109,"role":"protein","label":"cocida"},{"food":"limon","g":20,"role":"fixed"},{"food":"repollo","g":100,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"pimenton","g":80,"role":"veg"},{"food":"cebolla","g":50,"role":"veg"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Sazona lomo de cerdo magro con ajo, comino, sal y jugo de limón; déjala reposar 15 minutos.","Sella en una sartén antiadherente con 1 cucharadita de aceite, 5–6 minutos por lado hasta que esté completamente cocida (temperatura interna de 74 °C si usas termómetro); sin partes rosadas por dentro.","Deja reposar 3 minutos antes de cortar en tiras.","Ralla el repollo y la zanahoria, aliña con jugo de limón, sal y una cucharadita de aceite de oliva.","Corta el pimentón y la cebolla en tiras y saltéalos 6 minutos con una cucharadita de aceite hasta que estén dorados.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','cerdo','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-pechuga-de-pavo-en-brocheta-con-pimenton-y-cebolla-con-calabacin-salteado-y-habichuela-y-zanahoria-salteadas','Pechuga de pavo en brocheta con pimentón y cebolla con calabacín salteado y habichuela y zanahoria salteadas','dinner','pavo','pollo',38,328,35.6,28.7,9.4,11.3,'[{"food":"pavo","g":98,"role":"protein","label":"cocida"},{"food":"pimenton","g":50,"role":"veg"},{"food":"cebolla","g":60,"role":"veg"},{"food":"calabacin","g":160,"role":"veg"},{"food":"habichuela","g":90,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"aguacate","g":50,"role":"fat"}]'::jsonb,'["Corta pechuga de pavo en cubos de 3 cm y alterna en palitos con tiras de pimentón y cebolla.","Sazona con sal, ajo, comino y limón.","Asa en sartén o parrilla 12–15 minutos girando para que se cocine por todos los lados.","Corta el calabacín en medias lunas y saltéalo con cebolla 5 minutos a fuego alto para que no suelte agua.","Saltea la habichuela y la zanahoria en juliana con cebolla larga y 1 cucharadita de aceite 6 minutos; deben quedar tiernas pero crujientes.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','pavo','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-pechuga-de-pavo-a-la-plancha-con-ajo-y-limon-con-ensalada-de-lechuga-y-aguacate-y-pure-de-ahuyama','Pechuga de pavo a la plancha con ajo y limón con ensalada de lechuga y aguacate y puré de ahuyama','dinner','pavo','pollo',28,252.9,32.1,18.7,6.3,3.3,'[{"food":"pavo","g":98,"role":"protein","label":"cocida"},{"food":"limon","g":20,"role":"fixed"},{"food":"lechuga","g":80,"role":"veg"},{"food":"ahuyama","g":150,"role":"veg"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Sazona pechuga de pavo con ajo, comino, sal y jugo de limón; déjala reposar 15 minutos.","Sella en una sartén antiadherente con 1 cucharadita de aceite, 5–6 minutos por lado hasta que esté completamente cocida (temperatura interna de 74 °C si usas termómetro); sin partes rosadas por dentro.","Deja reposar 3 minutos antes de cortar en tiras.","Lava bien la lechuga, trocéala y mezcla con el aguacate en cubos, limón y sal.","Cocina la ahuyama en trozos 15 minutos, escúrrela y aplástala con sal y una pizca de comino.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','pavo','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-pechuga-de-pavo-desmechada-con-cebolla-y-pimenton-con-pimenton-y-cebolla-salteados-y-espinacas-con-champinones','Pechuga de pavo desmechada con cebolla y pimentón con pimentón y cebolla salteados y espinacas con champiñones','dinner','pavo','pollo',48,394.5,38.4,40.3,9.9,11,'[{"food":"pavo","g":98,"role":"protein","label":"cocida"},{"food":"cebolla","g":90,"role":"veg"},{"food":"pimenton","g":120,"role":"veg"},{"food":"espinaca","g":80,"role":"veg"},{"food":"champi","g":60,"role":"veg"},{"food":"aguacate","g":50,"role":"fat"},{"food":"arroz_int","g":60,"role":"carb"}]'::jsonb,'["Hierve pechuga de pavo en agua con cebolla, ajo y sal 25 minutos hasta que esté muy tierna.","Desmecha con dos tenedores.","Sofríe cebolla y pimentón en tiras con 1 cucharadita de aceite 5 minutos, agrega la carne desmechada y cocina 5 minutos más.","Corta el pimentón y la cebolla en tiras y saltéalos 6 minutos con una cucharadita de aceite hasta que estén dorados.","Saltea los champiñones laminados con ajo 4 minutos, añade la espinaca y cocina 2 minutos hasta que se marchite.","Sirve con una porción pequeña de arroz integral cocido (cena baja en carbohidrato)."]'::jsonb,array['cena','pavo','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-mini-pastel-de-carne-molida-magra-con-espinaca-con-habichuela-y-zanahoria-salteadas-y-berenjena-al-horno','Mini pastel de carne molida magra con espinaca con habichuela y zanahoria salteadas y berenjena al horno','dinner','res','res',43,389.8,38.2,29,15,9.7,'[{"food":"molida","g":113,"role":"protein","label":"cocida"},{"food":"espinaca","g":50,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"clara","g":33,"role":"protein"},{"food":"habichuela","g":90,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"berenjena","g":150,"role":"veg"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Calienta el horno a 190 °C.","Mezcla carne molida magra con espinaca picada, cebolla, 1 clara, sal y comino.","Llena moldes de muffin y hornea 22 minutos hasta que estén firmes y cocidos por dentro.","Saltea la habichuela y la zanahoria en juliana con cebolla larga y 1 cucharadita de aceite 6 minutos; deben quedar tiernas pero crujientes.","Corta la berenjena en rodajas, sazona con sal, ajo y comino y hornea a 200 °C por 20 minutos.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','res','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-albondigas-de-carne-molida-magra-al-horno-con-pure-de-ahuyama-y-ensalada-de-repollo-y-zanahoria','Albóndigas de carne molida magra al horno con puré de ahuyama y ensalada de repollo y zanahoria','dinner','res','res',43,491.1,39.2,48,17.5,11.1,'[{"food":"molida","g":113,"role":"protein","label":"cocida"},{"food":"cebolla","g":30,"role":"veg"},{"food":"clara","g":33,"role":"protein"},{"food":"ahuyama","g":150,"role":"veg"},{"food":"repollo","g":100,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"limon","g":10,"role":"fixed"},{"food":"aguacate","g":50,"role":"fat"},{"food":"arroz_int","g":60,"role":"carb"}]'::jsonb,'["Mezcla carne molida magra con cebolla rallada, ajo, sal, comino y 1 clara; forma bolitas de 4 cm.","Hornea a 200 °C por 18–20 minutos, volteando a la mitad, hasta que estén cocidas por dentro (sin rosado).","Sirve calientes.","Cocina la ahuyama en trozos 15 minutos, escúrrela y aplástala con sal y una pizca de comino.","Ralla el repollo y la zanahoria, aliña con jugo de limón, sal y una cucharadita de aceite de oliva.","Sirve con una porción pequeña de arroz integral cocido (cena baja en carbohidrato)."]'::jsonb,array['cena','res','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-carne-molida-magra-salteada-con-zanahoria-y-cebolla-con-espinacas-con-champinones-y-calabacin-salteado','Carne molida magra salteada con zanahoria y cebolla con espinacas con champiñones y calabacín salteado','dinner','res','res',28,352,36.6,19.9,15.2,6.4,'[{"food":"molida","g":113,"role":"protein","label":"cocida"},{"food":"cebolla","g":70,"role":"veg"},{"food":"zanahoria","g":40,"role":"veg"},{"food":"espinaca","g":80,"role":"veg"},{"food":"champi","g":60,"role":"veg"},{"food":"calabacin","g":160,"role":"veg"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Sofríe cebolla y zanahoria rallada con 1 cucharadita de aceite 4 minutos.","Agrega carne molida magra, sazona con comino y sal, y cocina 10 minutos desbaratando los grumos hasta que esté bien cocida.","Saltea los champiñones laminados con ajo 4 minutos, añade la espinaca y cocina 2 minutos hasta que se marchite.","Corta el calabacín en medias lunas y saltéalo con cebolla 5 minutos a fuego alto para que no suelte agua.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','res','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-bocachico-en-salsa-de-coco-ligera-con-berenjena-al-horno-y-ensalada-de-lechuga-y-aguacate','Bocachico en salsa de coco ligera con berenjena al horno y ensalada de lechuga y aguacate','dinner','bocachico','pescado',33,411.7,34.7,38.4,14.9,9.7,'[{"food":"bocachico","g":128,"role":"protein","label":"cocida"},{"food":"cebolla","g":30,"role":"veg"},{"food":"berenjena","g":150,"role":"veg"},{"food":"lechuga","g":80,"role":"veg"},{"food":"limon","g":10,"role":"fixed"},{"food":"aguacate","g":50,"role":"fat"},{"food":"arroz_int","g":60,"role":"carb"}]'::jsonb,'["Sofríe cebolla larga y ajo con una cucharadita de aceite 3 minutos.","Agrega la leche de coco light, sal y comino; cuando hierva, añade el filete de bocachico.","Tapa y cocina a fuego bajo 10–12 minutos hasta que esté bien cocido.","Corta la berenjena en rodajas, sazona con sal, ajo y comino y hornea a 200 °C por 20 minutos.","Lava bien la lechuga, trocéala y mezcla con el aguacate en cubos, limón y sal.","Sirve con una porción pequeña de arroz integral cocido (cena baja en carbohidrato)."]'::jsonb,array['cena','bocachico','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-bocachico-en-papillote-con-limon-y-cilantro-con-ensalada-de-repollo-y-zanahoria-y-pimenton-y-cebolla-salteados','Bocachico en papillote con limón y cilantro con ensalada de repollo y zanahoria y pimentón y cebolla salteados','dinner','bocachico','pescado',33,316.2,32.6,20.9,11.9,6.4,'[{"food":"bocachico","g":128,"role":"protein","label":"cocida"},{"food":"limon","g":25,"role":"fixed"},{"food":"repollo","g":100,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"pimenton","g":80,"role":"veg"},{"food":"cebolla","g":50,"role":"veg"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Pon el filete de bocachico sobre papel aluminio con rodajas de limón, cilantro, ajo y sal.","Cierra el paquete y hornea a 200 °C por 18–20 minutos hasta que esté bien cocido.","Ralla el repollo y la zanahoria, aliña con jugo de limón, sal y una cucharadita de aceite de oliva.","Corta el pimentón y la cebolla en tiras y saltéalos 6 minutos con una cucharadita de aceite hasta que estén dorados.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','bocachico','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-bocachico-a-la-plancha-con-limon-con-calabacin-salteado-y-habichuela-y-zanahoria-salteadas','Bocachico a la plancha con limón con calabacín salteado y habichuela y zanahoria salteadas','dinner','bocachico','pescado',23,349.6,34.8,23.7,14.7,9.7,'[{"food":"bocachico","g":128,"role":"protein","label":"cocida"},{"food":"limon","g":10,"role":"fixed"},{"food":"calabacin","g":160,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"habichuela","g":90,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"aguacate","g":50,"role":"fat"}]'::jsonb,'["Sazona el filete de bocachico con sal, ajo y limón.","Cocina en sartén antiadherente con 1 cucharadita de aceite, 4–5 minutos por lado, hasta que la carne se desmenuce con el tenedor y no quede translúcida.","Corta el calabacín en medias lunas y saltéalo con cebolla 5 minutos a fuego alto para que no suelte agua.","Saltea la habichuela y la zanahoria en juliana con cebolla larga y 1 cucharadita de aceite 6 minutos; deben quedar tiernas pero crujientes.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','bocachico','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-mojarra-en-papillote-con-limon-y-cilantro-con-ensalada-de-lechuga-y-aguacate-y-pure-de-ahuyama','Mojarra en papillote con limón y cilantro con ensalada de lechuga y aguacate y puré de ahuyama','dinner','mojarra','pescado',33,268.6,32.1,19.1,8.4,3.3,'[{"food":"mojarra","g":113,"role":"protein","label":"cocida"},{"food":"limon","g":25,"role":"fixed"},{"food":"lechuga","g":80,"role":"veg"},{"food":"ahuyama","g":150,"role":"veg"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Pon el filete de mojarra sobre papel aluminio con rodajas de limón, cilantro, ajo y sal.","Cierra el paquete y hornea a 200 °C por 18–20 minutos hasta que esté bien cocido.","Lava bien la lechuga, trocéala y mezcla con el aguacate en cubos, limón y sal.","Cocina la ahuyama en trozos 15 minutos, escúrrela y aplástala con sal y una pizca de comino.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','mojarra','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
