insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-camarones-en-salsa-de-coco-con-pimenton-y-cebolla-salteados-y-espinacas-con-champinones','Camarones en salsa de coco con pimentón y cebolla salteados y espinacas con champiñones','dinner','camaron','camaron',23,296,36.6,21.9,8.5,8.9,'[{"food":"camaron","g":124,"role":"protein","label":"cocida"},{"food":"cebolla","g":80,"role":"veg"},{"food":"pimenton","g":80,"role":"veg"},{"food":"espinaca","g":80,"role":"veg"},{"food":"champi","g":60,"role":"veg"},{"food":"aguacate","g":50,"role":"fat"}]'::jsonb,'["Sofríe cebolla y ajo con 1 cucharadita de aceite 3 minutos.","Agrega leche de coco light y sal; cuando hierva, añade los camarones y cocina 5 minutos hasta que estén completamente cocidos.","Corta el pimentón y la cebolla en tiras y saltéalos 6 minutos con una cucharadita de aceite hasta que estén dorados.","Saltea los champiñones laminados con ajo 4 minutos, añade la espinaca y cocina 2 minutos hasta que se marchite.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','camaron','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-camarones-salteados-con-pimenton-y-cebolla-con-habichuela-y-zanahoria-salteadas-y-berenjena-al-horno','Camarones salteados con pimentón y cebolla con habichuela y zanahoria salteadas y berenjena al horno','dinner','camaron','camaron',23,297.2,33.9,30.1,6.2,9.6,'[{"food":"camaron","g":124,"role":"protein","label":"cocida"},{"food":"pimenton","g":50,"role":"veg"},{"food":"cebolla","g":30,"role":"veg"},{"food":"habichuela","g":90,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"berenjena","g":150,"role":"veg"},{"food":"aceite","g":5,"role":"fat"}]'::jsonb,'["Saltea cebolla y pimentón en tiras con 1 cucharadita de aceite 4 minutos.","Agrega los camarones sazonados con comino y sal; cocina 4 minutos más hasta que estén firmes y rosados.","Saltea la habichuela y la zanahoria en juliana con cebolla larga y 1 cucharadita de aceite 6 minutos; deben quedar tiernas pero crujientes.","Corta la berenjena en rodajas, sazona con sal, ajo y comino y hornea a 200 °C por 20 minutos.","Cena baja en carbohidrato: no agregues arroz ni papa; prioriza la proteína y las verduras."]'::jsonb,array['cena','camaron','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
insert into public.recipes (slug,name,kind,family,art,time_min,kcal,protein_g,carbs_g,fat_g,fiber_g,lines,steps,tags,caffeine_mg,preg_note) values ('dinner-camarones-salteados-al-ajo-con-limon-con-pure-de-ahuyama-y-ensalada-de-repollo-y-zanahoria','Camarones salteados al ajo con limón con puré de ahuyama y ensalada de repollo y zanahoria','dinner','camaron','camaron',20,384.7,35.7,46.1,8.7,10.6,'[{"food":"camaron","g":124,"role":"protein","label":"cocida"},{"food":"limon","g":20,"role":"fixed"},{"food":"ahuyama","g":150,"role":"veg"},{"food":"repollo","g":100,"role":"veg"},{"food":"zanahoria","g":50,"role":"veg"},{"food":"aguacate","g":50,"role":"fat"},{"food":"arroz_int","g":60,"role":"carb"}]'::jsonb,'["Sazona los camarones limpios con sal y limón.","Saltea ajo picado en 1 cucharadita de aceite 30 segundos; añade los camarones y cocina 3–4 minutos hasta que estén bien rosados y firmes.","Cocina la ahuyama en trozos 15 minutos, escúrrela y aplástala con sal y una pizca de comino.","Ralla el repollo y la zanahoria, aliña con jugo de limón, sal y una cucharadita de aceite de oliva.","Sirve con una porción pequeña de arroz integral cocido (cena baja en carbohidrato)."]'::jsonb,array['cena','camaron','baja en carbohidrato']::text[],0,null) on conflict (slug) do update set name=excluded.name, kind=excluded.kind, family=excluded.family, art=excluded.art, time_min=excluded.time_min, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, lines=excluded.lines, steps=excluded.steps, tags=excluded.tags, caffeine_mg=excluded.caffeine_mg, preg_note=excluded.preg_note;
