insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('cuadriceps-isometrico','Cuádriceps isométrico (contracción pierna estirada)',array['knee_block']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":45,"impact":"none","isometric":true,"unilateral":false,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":0},"slug":"cuadriceps-isometrico","name":"Cuádriceps isométrico (contracción pierna estirada)","groups":["knee_block"],"muscles":["cuádriceps","vasto medial"],"equipment":["toalla enrollada"],"homeOk":true,"repsMin":10,"repsMax":10,"tempo":"5 s de contracción","safeRomText":"Rodilla completamente estirada, sin movimiento: solo contraes el muslo.","cues":["Pierna estirada con una toalla enrollada bajo la rodilla","Empuja la rodilla contra la toalla y levanta ligeramente el talón","Respira con normalidad; no aguantes el aire"],"easier":"Contracción de 3 s con menos fuerza (50 % del esfuerzo).","harder":"Contracción de 8 s a máximo esfuerzo cómodo, o pasa a elevación de pierna recta.","regressionSlug":null,"progressionSlug":"elevacion-pierna-recta","art":"quad_set"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('elevacion-pierna-recta','Elevación de pierna recta acostado',array['knee_block']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":60,"impact":"none","isometric":false,"unilateral":true,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":0},"slug":"elevacion-pierna-recta","name":"Elevación de pierna recta acostado","groups":["knee_block"],"muscles":["cuádriceps","flexores de cadera"],"equipment":[],"homeOk":true,"repsMin":12,"repsMax":12,"tempo":"2-1-2-0","safeRomText":"La rodilla se mantiene estirada todo el tiempo; el movimiento sale de la cadera.","cues":["Contrae el cuádriceps antes de levantar","Sube hasta la altura de la otra rodilla, no más","Baja lento sin dejar caer la pierna"],"easier":"Cuádriceps isométrico, o eleva solo 15 cm.","harder":"Añade tobillera de 1 a 2 kg.","regressionSlug":"cuadriceps-isometrico","progressionSlug":"extension-terminal-rodilla-banda","art":"slr"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('extension-terminal-rodilla-banda','Extensión terminal de rodilla con banda (TKE)',array['knee_block']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":60,"impact":"none","isometric":false,"unilateral":true,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":30},"slug":"extension-terminal-rodilla-banda","name":"Extensión terminal de rodilla con banda (TKE)","groups":["knee_block"],"muscles":["cuádriceps","vasto medial"],"equipment":["banda elástica","anclaje"],"homeOk":true,"repsMin":15,"repsMax":15,"tempo":"2-2-2-0","romByDx":{"patellofemoral":{"minDeg":0,"maxDeg":20},"post_surgery":{"minDeg":0,"maxDeg":20}},"safeRomText":"Solo los últimos 0–30° de extensión: parte con la rodilla apenas flexionada y termina estirada.","cues":["Banda justo detrás de la rodilla, pie firme en el suelo","Estira la rodilla empujando contra la banda","Pausa de 2 s con el muslo contraído arriba"],"easier":"Banda de menor resistencia o sin banda, solo la contracción.","harder":"Banda más fuerte o pausa de 5 s arriba.","regressionSlug":"elevacion-pierna-recta","progressionSlug":"sentadilla-isometrica-pared","art":"tke"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('sentadilla-isometrica-pared','Sentadilla isométrica en pared a 45–60°',array['knee_block']::text[],1,'{}'::text[],'{"sets":3,"unit":"seconds","restSec":60,"impact":"none","isometric":true,"unilateral":false,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":45,"maxDeg":60},"slug":"sentadilla-isometrica-pared","name":"Sentadilla isométrica en pared a 45–60°","groups":["knee_block"],"muscles":["cuádriceps","glúteos"],"equipment":["pared"],"homeOk":true,"repsMin":20,"repsMax":40,"tempo":"Mantén la posición","romByDx":{"patellofemoral":{"minDeg":30,"maxDeg":45},"post_surgery":{"minDeg":30,"maxDeg":45},"osteoarthritis":{"minDeg":30,"maxDeg":60},"patellar_tendinitis":{"minDeg":45,"maxDeg":60}},"safeRomText":"Rodillas flexionadas 45–60°, bastante por encima de la sentadilla a 90°. Nunca bajes a 90° en la fase 1.","cues":["Espalda apoyada en la pared, pies a la anchura de caderas","Rodillas alineadas con el segundo dedo, sin pasar la punta del pie","Peso repartido en los talones"],"easier":"Flexión de 30–45° y 15–20 s.","harder":"Sube a 40 s, o pasa a sentarse y pararse del banco alto.","regressionSlug":"extension-terminal-rodilla-banda","progressionSlug":"sentarse-y-pararse-banco-alto","art":"wall_sit"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('puente-de-gluteo','Puente de glúteo',array['knee_block']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":60,"impact":"none","isometric":false,"unilateral":false,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":60,"maxDeg":90},"slug":"puente-de-gluteo","name":"Puente de glúteo","groups":["knee_block"],"muscles":["glúteos","isquiotibiales"],"equipment":[],"homeOk":true,"repsMin":12,"repsMax":15,"tempo":"2-1-2-0","safeRomText":"Rodillas flexionadas unos 70–90° con los pies apoyados; el esfuerzo va a la cadera, no a la rodilla.","cues":["Talones bajo las rodillas, costillas abajo","Empuja con los talones hasta alinear hombro, cadera y rodilla","Aprieta glúteos 1 s arriba sin arquear la espalda"],"easier":"Rango corto y sin pausa.","harder":"Pausa de 3 s arriba, banda sobre las rodillas, o pasa a hip thrust.","regressionSlug":null,"progressionSlug":"hip-thrust","art":"bridge"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('clamshell-banda','Clamshell con banda',array['knee_block']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":60,"impact":"none","isometric":false,"unilateral":true,"minPhase":1,"bodyweight":false,"blockedFor":[],"safeRom":{"minDeg":45,"maxDeg":60},"slug":"clamshell-banda","name":"Clamshell con banda","groups":["knee_block"],"muscles":["glúteo medio","rotadores de cadera"],"equipment":["banda elástica"],"homeOk":true,"repsMin":12,"repsMax":15,"tempo":"2-1-2-0","safeRomText":"Rodillas flexionadas unos 45–60° acostado de lado; la rodilla solo sirve de palanca, el trabajo es de cadera.","cues":["Caderas apiladas y pies juntos","Abre la rodilla de arriba sin rotar la pelvis","Regresa controlado, sin soltar la banda"],"easier":"Sin banda.","harder":"Banda más fuerte o pausa de 3 s arriba.","regressionSlug":null,"progressionSlug":"caminata-lateral-banda","art":"clamshell"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('caminata-lateral-banda','Caminata lateral con banda',array['knee_block']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":60,"impact":"none","isometric":false,"unilateral":false,"minPhase":1,"bodyweight":false,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":30},"slug":"caminata-lateral-banda","name":"Caminata lateral con banda","groups":["knee_block"],"muscles":["glúteo medio","abductores"],"equipment":["banda elástica"],"homeOk":true,"repsMin":12,"repsMax":15,"tempo":"Pasos lentos y controlados","romByDx":{"patellofemoral":{"minDeg":0,"maxDeg":20},"meniscus":{"minDeg":0,"maxDeg":20}},"safeRomText":"Rodillas casi estiradas (hasta 30° de flexión), sin sentadilla profunda: ponte de pie más erguido si molesta.","cues":["Banda sobre las rodillas, pies a la anchura de caderas","Paso lateral corto, rodilla alineada con el pie","No dejes que la rodilla se vaya hacia dentro"],"easier":"Banda ligera, apoyándote con una mano en una pared.","harder":"Banda más fuerte o banda a la altura de los tobillos.","regressionSlug":"clamshell-banda","progressionSlug":"abduccion-maquina","art":"side_walk"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('elevacion-de-talones','Elevación de talones',array['knee_block']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":60,"impact":"none","isometric":false,"unilateral":false,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":10},"slug":"elevacion-de-talones","name":"Elevación de talones","groups":["knee_block"],"muscles":["gemelos","sóleo"],"equipment":["pared o barra de apoyo"],"homeOk":true,"repsMin":15,"repsMax":15,"tempo":"2-1-2-0","safeRomText":"Rodillas estiradas, sin bloquearlas con fuerza; la carga va a los tobillos, no a la rodilla.","cues":["Apóyate ligeramente en la pared","Sube sobre los metatarsos sin que los tobillos se abran","Baja en 2 segundos hasta tocar el suelo"],"easier":"Hazlo sentado con un peso sobre las rodillas.","harder":"Con mancuernas en las manos o a una pierna.","regressionSlug":"elevacion-talones-sentado","progressionSlug":null,"art":"calf_raise"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('equilibrio-una-pierna','Equilibrio en una pierna con apoyo cerca',array['knee_block']::text[],1,'{}'::text[],'{"sets":3,"unit":"seconds","restSec":30,"impact":"none","isometric":true,"unilateral":true,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":15},"slug":"equilibrio-una-pierna","name":"Equilibrio en una pierna con apoyo cerca","groups":["knee_block"],"muscles":["estabilizadores de cadera","tobillo","cuádriceps"],"equipment":["pared o silla firme"],"homeOk":true,"repsMin":20,"repsMax":30,"tempo":"Mantén la posición","safeRomText":"Rodilla de apoyo casi estirada, ligeramente suelta; no la bloquees.","cues":["Mano cerca de la pared o la silla, lista para apoyarte","Cadera nivelada y mirada al frente","Rodilla alineada sobre el segundo dedo del pie"],"easier":"Toca la pared con las yemas o mantén los 2 pies cerca.","harder":"Sin apoyo, o con los ojos cerrados un instante, o sobre cojín firme.","regressionSlug":null,"progressionSlug":null,"art":"single_leg_balance"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('isometrico-isquiotibiales-talon','Isométrico de isquiotibiales (talón al suelo)',array['knee_block']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":45,"impact":"none","isometric":true,"unilateral":true,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":20,"maxDeg":30},"slug":"isometrico-isquiotibiales-talon","name":"Isométrico de isquiotibiales (talón al suelo)","groups":["knee_block"],"muscles":["isquiotibiales"],"equipment":[],"homeOk":true,"repsMin":10,"repsMax":10,"tempo":"5 s de contracción","safeRomText":"Sentado, pierna con unos 20–30° de flexión y el talón empujando al suelo, sin movimiento.","cues":["Sentado con el talón apoyado y la rodilla algo flexionada","Empuja el talón hacia atrás contra el suelo","Aumenta la fuerza poco a poco, sin tirones"],"easier":"Contracción de 3 s a la mitad del esfuerzo.","harder":"Contracción de 8 s con más fuerza, o pasa a curl femoral.","regressionSlug":null,"progressionSlug":"curl-femoral-maquina","art":"leg_curl"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('isometrico-aductores-balon','Isométrico de aductores con balón',array['knee_block']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":45,"impact":"none","isometric":true,"unilateral":false,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":60,"maxDeg":90},"slug":"isometrico-aductores-balon","name":"Isométrico de aductores con balón","groups":["knee_block"],"muscles":["aductores"],"equipment":["balón o cojín"],"homeOk":true,"repsMin":10,"repsMax":10,"tempo":"5 s de contracción","safeRomText":"Sentado con las rodillas flexionadas a unos 70–90°, solo aprietas; sin movimiento de la rodilla.","cues":["Balón o cojín entre las rodillas","Aprieta con suavidad y mantén","Espalda recta y respiración continua"],"easier":"Aprieta al 50 % de fuerza durante 3 s.","harder":"Aprieta con más fuerza o pasa a aducción en máquina.","regressionSlug":null,"progressionSlug":"aduccion-maquina","art":"hip_adduction"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('elevacion-talones-sentado','Elevación de talones sentado',array['knee_block','leg_b']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":60,"impact":"none","isometric":false,"unilateral":false,"minPhase":1,"bodyweight":false,"blockedFor":[],"safeRom":{"minDeg":80,"maxDeg":90},"slug":"elevacion-talones-sentado","name":"Elevación de talones sentado","groups":["knee_block","leg_b"],"muscles":["sóleo","gemelos"],"equipment":["banco","mancuerna"],"homeOk":true,"repsMin":15,"repsMax":20,"tempo":"2-1-2-0","safeRomText":"Sentado con las rodillas a 90°: casi no hay carga en la articulación de la rodilla.","cues":["Mancuerna sobre los muslos, cerca de las rodillas","Sube los talones lo más alto posible","Baja despacio sin rebotar"],"easier":"Sin peso.","harder":"Más peso o pasa a elevación de talones de pie.","regressionSlug":null,"progressionSlug":"elevacion-de-talones","art":"calf_raise"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('sentarse-y-pararse-banco-alto','Sentarse y pararse de un banco alto',array['leg_a']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":75,"impact":"none","isometric":false,"unilateral":false,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":70},"slug":"sentarse-y-pararse-banco-alto","name":"Sentarse y pararse de un banco alto","groups":["leg_a"],"muscles":["cuádriceps","glúteos"],"equipment":["banco alto o silla firme"],"homeOk":true,"repsMin":8,"repsMax":12,"tempo":"3-0-1-0","romByDx":{"patellofemoral":{"minDeg":0,"maxDeg":45},"post_surgery":{"minDeg":0,"maxDeg":60},"osteoarthritis":{"minDeg":0,"maxDeg":60},"meniscus":{"minDeg":0,"maxDeg":60}},"safeRomText":"Usa un banco alto: la cadera queda por encima de la rodilla y la flexión no pasa de unos 60–70°.","cues":["Pies ligeramente atrás, anchura de caderas","Cadera atrás y baja controlado hasta rozar el banco","Empuja con los talones y rodillas alineadas con los pies"],"easier":"Banco más alto o apóyate con las manos.","harder":"Sostén una mancuerna al pecho o prueba un banco algo más bajo sin pasar de 70°.","regressionSlug":"sentadilla-isometrica-pared","progressionSlug":"prensa-piernas-rango-protegido","art":"sit_to_stand"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('prensa-piernas-rango-protegido','Prensa de piernas en rango protegido',array['leg_a']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":90,"impact":"none","isometric":false,"unilateral":false,"minPhase":1,"bodyweight":false,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":90},"slug":"prensa-piernas-rango-protegido","name":"Prensa de piernas en rango protegido","groups":["leg_a"],"muscles":["cuádriceps","glúteos","isquiotibiales"],"equipment":["prensa de piernas"],"homeOk":false,"repsMin":10,"repsMax":12,"tempo":"3-0-2-0","romByDx":{"meniscus":{"minDeg":0,"maxDeg":60},"acl":{"minDeg":0,"maxDeg":60},"mcl":{"minDeg":0,"maxDeg":60},"patellofemoral":{"minDeg":0,"maxDeg":45},"osteoarthritis":{"minDeg":0,"maxDeg":60},"patellar_tendinitis":{"minDeg":0,"maxDeg":60},"post_surgery":{"minDeg":0,"maxDeg":60}},"safeRomText":"Sin diagnóstico 0–90°; con meniscos, LCA, LCM, tendinitis, artrosis o cirugía 0–60°; con dolor patelofemoral 0–45°. Pon un tope en la máquina.","cues":["Pies a la anchura de caderas, espalda y glúteos pegados al respaldo","Baja hasta el tope marcado, sin que se levante la pelvis","Empuja con toda la planta y no bloquees la rodilla arriba"],"easier":"Menos peso y rango más corto (0–45°).","harder":"Más carga manteniendo el rango, o pasa a prensa a una pierna.","regressionSlug":"sentarse-y-pararse-banco-alto","progressionSlug":"prensa-una-pierna","art":"leg_press"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('curl-femoral-maquina','Curl femoral en máquina',array['leg_a']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":75,"impact":"none","isometric":false,"unilateral":false,"minPhase":1,"bodyweight":false,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":90},"slug":"curl-femoral-maquina","name":"Curl femoral en máquina","groups":["leg_a"],"muscles":["isquiotibiales"],"equipment":["máquina de curl femoral sentado"],"homeOk":false,"repsMin":10,"repsMax":12,"tempo":"2-1-3-0","romByDx":{"acl":{"minDeg":0,"maxDeg":60},"post_surgery":{"minDeg":0,"maxDeg":60}},"safeRomText":"Rango 0–90° sin dolor; en LCA o posoperatorio solo hasta unos 60° y con aval del especialista.","cues":["Rodillas alineadas con el eje de la máquina","Flexiona sin arquear la espalda","Vuelve en 3 segundos, sin dejar caer el peso"],"easier":"Menos peso o isométrico de isquiotibiales.","harder":"Más carga o bajar con una sola pierna.","regressionSlug":"isometrico-isquiotibiales-talon","progressionSlug":"curl-femoral-acostado","art":"leg_curl"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('extension-cuadriceps-90-45','Extensión de cuádriceps 90°–45° (si aplica)',array['leg_a']::text[],2,array['patellofemoral']::text[],'{"sets":3,"unit":"reps","restSec":75,"impact":"none","isometric":false,"unilateral":false,"minPhase":2,"bodyweight":false,"blockedFor":["patellofemoral"],"safeRom":{"minDeg":45,"maxDeg":90},"slug":"extension-cuadriceps-90-45","name":"Extensión de cuádriceps 90°–45° (si aplica)","groups":["leg_a"],"muscles":["cuádriceps"],"equipment":["máquina de extensión de piernas"],"homeOk":false,"repsMin":10,"repsMax":12,"tempo":"2-1-3-0","romByDx":{"acl":{"minDeg":60,"maxDeg":90},"post_surgery":{"minDeg":60,"maxDeg":90},"meniscus":{"minDeg":45,"maxDeg":90}},"safeRomText":"Solo entre 90° y 45° de flexión, con carga ligera y tope fijo: los últimos 45° bajo carga irritan la rótula. En LCA o posoperatorio solo con aval del especialista.","cues":["Ajusta el tope para no pasar de 45°","Extiende con control, sin balancear la espalda","Baja lento y con peso ligero"],"easier":"Cuádriceps isométrico o menos peso.","harder":"Un poco más de carga, siempre ligera y sin dolor.","regressionSlug":"cuadriceps-isometrico","progressionSlug":null,"art":"leg_extension"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('aduccion-maquina','Aducción en máquina',array['leg_a']::text[],1,'{}'::text[],'{"sets":3,"unit":"reps","restSec":60,"impact":"none","isometric":false,"unilateral":false,"minPhase":1,"bodyweight":false,"blockedFor":[],"safeRom":{"minDeg":60,"maxDeg":90},"slug":"aduccion-maquina","name":"Aducción en máquina","groups":["leg_a"],"muscles":["aductores"],"equipment":["máquina de aducción"],"homeOk":false,"repsMin":12,"repsMax":15,"tempo":"2-1-2-0","safeRomText":"Sentado con las rodillas a 70–90° y rango de apertura moderado; evita abrir al máximo.","cues":["Espalda apoyada y pelvis quieta","Cierra las piernas suave, sin tirón","Abre controlado, dentro de un rango cómodo"],"easier":"Menos peso y menor apertura.","harder":"Más peso con pausa de 2 s al cerrar.","regressionSlug":"isometrico-aductores-balon","progressionSlug":null,"art":"hip_adduction"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
