insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('movilidad-cadera-circulos','Movilidad de cadera (círculos y apertura)',array['warmup']::text[],1,'{}'::text[],'{"sets":2,"unit":"reps","restSec":15,"impact":"none","isometric":false,"unilateral":true,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":null,"slug":"movilidad-cadera-circulos","name":"Movilidad de cadera (círculos y apertura)","groups":["warmup"],"muscles":["cadera","glúteos"],"equipment":[],"homeOk":true,"repsMin":10,"repsMax":10,"tempo":"Lento y controlado","safeRomText":"Círculos amplios con la rodilla casi estirada o ligeramente flexionada; sin llevar la rodilla a flexión profunda.","cues":["Apóyate en una pared","Haz círculos grandes desde la cadera","Tronco quieto"],"easier":"Círculos más pequeños.","harder":"Mayor amplitud, sin dolor.","regressionSlug":null,"progressionSlug":null,"art":"mobility_hip"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('movilidad-tobillo','Movilidad de tobillo',array['warmup']::text[],1,'{}'::text[],'{"sets":2,"unit":"reps","restSec":15,"impact":"none","isometric":false,"unilateral":true,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":null,"slug":"movilidad-tobillo","name":"Movilidad de tobillo","groups":["warmup"],"muscles":["tobillo","gemelos"],"equipment":[],"homeOk":true,"repsMin":10,"repsMax":12,"tempo":"Lento","safeRomText":"Sentado con la rodilla a unos 90° o de pie con apoyo; sin cargar peso en la rodilla.","cues":["Dibuja el abecedario con el pie","Mueve solo el tobillo","Amplitud cómoda en ambas direcciones"],"easier":"Menor recorrido.","harder":"Añade empuje del pie contra una banda.","regressionSlug":null,"progressionSlug":null,"art":"mobility_ankle"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('circuito-activacion','Circuito de activación (puente + clamshell + TKE)',array['warmup']::text[],1,'{}'::text[],'{"sets":2,"unit":"reps","restSec":30,"impact":"none","isometric":false,"unilateral":false,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":60},"slug":"circuito-activacion","name":"Circuito de activación (puente + clamshell + TKE)","groups":["warmup"],"muscles":["glúteos","glúteo medio","cuádriceps"],"equipment":["banda elástica"],"homeOk":true,"repsMin":10,"repsMax":10,"tempo":"Controlado","safeRomText":"Mismos rangos que los ejercicios originales: puente a 70–90°, clamshell a 45–60° y TKE solo en los últimos grados de extensión.","cues":["10 puentes, 10 clamshell por lado y 10 TKE por lado","Sin dolor y sin velocidad","Siente glúteos y cuádriceps encendidos"],"easier":"1 serie con menos repeticiones.","harder":"Añade banda en el puente.","regressionSlug":null,"progressionSlug":null,"art":"bridge"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('estiramiento-cuadriceps','Estiramiento de cuádriceps (de pie con apoyo o de lado)',array['stretch']::text[],1,'{}'::text[],'{"sets":2,"unit":"seconds","restSec":15,"impact":"none","isometric":true,"unilateral":true,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":90},"slug":"estiramiento-cuadriceps","name":"Estiramiento de cuádriceps (de pie con apoyo o de lado)","groups":["stretch"],"muscles":["cuádriceps"],"equipment":["pared"],"homeOk":true,"repsMin":30,"repsMax":30,"tempo":"Sostén sin rebotar","safeRomText":"Flexiona la rodilla hasta sentir tensión en el muslo, sin dolor en la rótula ni forzar el talón al glúteo.","cues":["Pelvis neutra, sin arquear la espalda","Rodillas juntas y tensión suave","Respira lento"],"easier":"Usa una toalla en el tobillo para reducir la flexión.","harder":"Lleva el talón más cerca del glúteo sin dolor.","regressionSlug":null,"progressionSlug":null,"art":"stretch_quad"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('estiramiento-isquiotibiales','Estiramiento de isquiotibiales',array['stretch']::text[],1,'{}'::text[],'{"sets":2,"unit":"seconds","restSec":15,"impact":"none","isometric":true,"unilateral":true,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":20},"slug":"estiramiento-isquiotibiales","name":"Estiramiento de isquiotibiales","groups":["stretch"],"muscles":["isquiotibiales"],"equipment":["toalla o banda"],"homeOk":true,"repsMin":30,"repsMax":30,"tempo":"Sostén sin rebotar","safeRomText":"Acostado, pierna elevada con la rodilla casi estirada: puede quedar una pequeña flexión, sin forzarla.","cues":["Cabeza y espalda apoyadas","Toalla en la planta del pie","Estira hasta tensión suave, no dolor"],"easier":"Rodilla algo más flexionada.","harder":"Eleva más la pierna manteniendo la rodilla estirada.","regressionSlug":null,"progressionSlug":null,"art":"stretch_ham"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('estiramiento-pantorrillas','Estiramiento de pantorrillas',array['stretch']::text[],1,'{}'::text[],'{"sets":2,"unit":"seconds","restSec":15,"impact":"none","isometric":true,"unilateral":true,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":15},"slug":"estiramiento-pantorrillas","name":"Estiramiento de pantorrillas","groups":["stretch"],"muscles":["gemelos","sóleo"],"equipment":["pared"],"homeOk":true,"repsMin":30,"repsMax":30,"tempo":"Sostén sin rebotar","safeRomText":"Pierna de atrás estirada con el talón en el suelo; la rodilla delantera se flexiona poco.","cues":["Talón de atrás siempre apoyado","Pie apuntando al frente","Inclina el cuerpo hasta sentir el estiramiento"],"easier":"Menos inclinación.","harder":"Alarga la distancia entre pies.","regressionSlug":null,"progressionSlug":null,"art":"stretch_calf"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('estiramiento-flexores-cadera','Estiramiento de flexores de cadera',array['stretch']::text[],1,'{}'::text[],'{"sets":2,"unit":"seconds","restSec":15,"impact":"none","isometric":true,"unilateral":true,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":0,"maxDeg":90},"slug":"estiramiento-flexores-cadera","name":"Estiramiento de flexores de cadera","groups":["stretch"],"muscles":["psoas","recto femoral"],"equipment":["colchoneta o cojín"],"homeOk":true,"repsMin":30,"repsMax":30,"tempo":"Sostén sin rebotar","safeRomText":"Evita arrodillarte con peso sobre la rótula: hazlo de pie con apoyo o acostado en el borde de la cama.","cues":["Pelvis ligeramente hacia atrás","Siente el estiramiento al frente de la cadera","No arquees la zona lumbar"],"easier":"Menor recorrido y apoyo en una pared.","harder":"Eleva el brazo del mismo lado.","regressionSlug":null,"progressionSlug":null,"art":"stretch_hip_flexor"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('estiramiento-gluteo-figura-4','Estiramiento de glúteo (figura 4 acostado)',array['stretch']::text[],1,'{}'::text[],'{"sets":2,"unit":"seconds","restSec":15,"impact":"none","isometric":true,"unilateral":true,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":60,"maxDeg":90},"slug":"estiramiento-gluteo-figura-4","name":"Estiramiento de glúteo (figura 4 acostado)","groups":["stretch"],"muscles":["glúteos","piriforme"],"equipment":["colchoneta"],"homeOk":true,"repsMin":30,"repsMax":30,"tempo":"Sostén sin rebotar","safeRomText":"Rodilla de la pierna cruzada cómoda, sin torcerla: la tensión debe sentirse en el glúteo, no en la rodilla.","cues":["Tobillo sobre la rodilla contraria","Tira del muslo hacia el pecho","Presiona suave la rodilla de arriba"],"easier":"Mantén el pie de apoyo en el suelo.","harder":"Acerca más el muslo al pecho.","regressionSlug":null,"progressionSlug":null,"art":"stretch_glute"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
