insert into public.exercises (slug,name,groups,min_phase,blocked_for,data) values ('movilidad-cadera-90-90','Movilidad de cadera 90/90 sentado',array['mobility']::text[],1,'{}'::text[],'{"sets":2,"unit":"reps","restSec":15,"impact":"none","isometric":false,"unilateral":false,"minPhase":1,"bodyweight":true,"blockedFor":[],"safeRom":{"minDeg":60,"maxDeg":90},"slug":"movilidad-cadera-90-90","name":"Movilidad de cadera 90/90 sentado","groups":["mobility"],"muscles":["rotadores de cadera","glúteos"],"equipment":["colchoneta"],"homeOk":true,"repsMin":6,"repsMax":8,"tempo":"Lento","safeRomText":"Rodillas a unos 90° sin torsión dolorosa; si molesta, abre más la posición o siéntate en una silla.","cues":["Espalda erguida","Cambia de lado sin usar las manos si es posible","Sin dolor en las rodillas"],"easier":"Siéntate sobre un cojín o ábrete más.","harder":"Cambia de lado sin apoyo de las manos.","regressionSlug":null,"progressionSlug":null,"art":"mobility_hip"}'::jsonb) on conflict (slug) do update set name=excluded.name, groups=excluded.groups, min_phase=excluded.min_phase, blocked_for=excluded.blocked_for, data=excluded.data;
